def convert_fp16_to_fp32(path):
  model = onnx.load(path)
  for i in model.graph.initializer:
    if i.data_type == 10:
      attributeproto_fp16_to_fp32(i)
  for i in itertools.chain(model.graph.input, model.graph.output):
    [IF_MASK]
      i.type.tensor_type.elem_type = 1
  for i in model.graph.node:
    for a in i.attribute:
      if hasattr(a, 't'):
        if a.t.data_type == 10:
          attributeproto_fp16_to_fp32(a.t)
  return model.SerializeToString()

def _format_instance_mapping(self, ctxt, instance_ref):
    root_device_name = instance_ref['root_device_name']
    if root_device_name is None:
        return _DEFAULT_MAPPINGS

    mappings = {}
    mappings['ami'] = block_device.strip_dev(root_device_name)
    mappings['root'] = root_device_name
    default_ephemeral_device = instance_ref.get('default_ephemeral_device')
    [IF_MASK]
        mappings['ephemeral0'] = default_ephemeral_device
    default_swap_device = instance_ref.get('default_swap_device')
    if default_swap_device:
        mappings['swap'] = default_swap_device
    ebs_devices = []


    for bdm in db.block_device_mapping_get_all_by_instance(
        ctxt, instance_ref['id']):
        if bdm['no_device']:
            continue


        if (bdm['volume_id'] or bdm['snapshot_id']):
            ebs_devices.append(bdm['device_name'])
            continue

        virtual_name = bdm['virtual_name']
        if not virtual_name:
            continue

        if block_device.is_swap_or_ephemeral(virtual_name):
            mappings[virtual_name] = bdm['device_name']




    if ebs_devices:
        nebs = 0
        ebs_devices.sort()
        for ebs in ebs_devices:
            mappings['ebs%d' % nebs] = ebs
            nebs += 1

    return mappings

def _add_aliases_to_namespace(namespace, *exprs):


    for expr in exprs:
        if hasattr(expr, 'alias') and isinstance(expr, sympy.FunctionClass):
            if namespace.has_key(str(expr)):
                if namespace[str(expr)] != expr.alias:
                    warnings.warn('two aliases with the same name were found')
            namespace[str(expr)] = expr.alias

        if hasattr(expr, 'func'):
            if isinstance(expr.func, sympy.FunctionClass) and hasattr(expr.func, 'alias'):
                if namespace.has_key(expr.func.__name__):
                    [IF_MASK]
                        warnings.warn('two aliases with the same name were found')
                namespace[expr.func.__name__] = expr.func.alias
        if hasattr(expr, 'args'):
            try:
                _add_aliases_to_namespace(namespace, *expr.args)
            except TypeError:
                pass
    return namespace

