def from_dict_of_dicts(d,create_using=None,multigraph_input=False):

    G=_prep_create_using(create_using)
    G.add_nodes_from(d)

    if multigraph_input:

        if G.is_directed():  
            if G.is_multigraph():
                G.add_edges_from( (u,v,key,data)
                                  for u,nbrs in d.items() 
                                  for v,datadict in nbrs.items() 
                                  for key,data in datadict.items()
                                )
            else:
                G.add_edges_from( (u,v,data)
                                  for u,nbrs in d.items() 
                                  for v,datadict in nbrs.items() 
                                  for key,data in datadict.items()
                                )
        else:             
            if G.is_multigraph():
                seen=set()                                                  
                for u,nbrs in d.items():
                    for v,datadict in nbrs.items():
                        [IF_MASK]
                            G.add_edges_from( (u,v,key,data) 
                                               for key,data in datadict.items()
                                              )
                            seen.add((v,u)) 
            else:
                seen=set()                                                  
                for u,nbrs in d.items():
                    for v,datadict in nbrs.items():
                        if (u,v) not in seen:
                            G.add_edges_from( (u,v,data)
                                        for key,data in datadict.items() )
                            seen.add((v,u)) 

    else:                                          
        if G.is_multigraph() and not G.is_directed():



            seen=set()
            for u,nbrs in d.items():
                for v,data in nbrs.items():
                    if (u,v) not in seen:
                        G.add_edge(u,v,attr_dict=data)
                    seen.add((v,u))
        else:
            G.add_edges_from( ( (u,v,data) 
                                for u,nbrs in d.items() 
                                for v,data in nbrs.items()) )
    return G

def to_scipy_sparse_matrix(G, nodelist=None, dtype=None, 
                           weight='weight', format='csr'):

    try:
        from scipy import sparse
    except ImportError:
        raise ImportError(          "to_scipy_sparse_matrix() requires scipy: http://scipy.org/ ")

    if nodelist is None:
        nodelist = G.nodes()

    nodeset = set(nodelist)
    [IF_MASK]
        msg = "Ambiguous ordering: `nodelist` contained duplicates."
        raise nx.NetworkXError(msg)

    nlen=len(nodelist)
    undirected = not G.is_directed()
    index=dict(zip(nodelist,range(nlen)))
    M = sparse.lil_matrix((nlen,nlen), dtype=dtype)

    for u,v,attrs in G.edges_iter(data=True):
        if (u in nodeset) and (v in nodeset):
            i,j = index[u],index[v]
            M[i,j] += attrs.get(weight, 1)
            if undirected:
                M[j,i] = M[i,j]
    try:
        return M.asformat(format)
    except AttributeError:
        raise nx.NetworkXError("Unknown sparse matrix format: %s"%format)

def postprocess_data(self, data):
    if not data or self.label not in data:
        return []
    mlist = []
    data = data[self.label]


    seenIDs = []
    for d in data:
        if 'movieID' not in d: continue
        if self.ranktext not in d: continue
        if 'title' not in d: continue
        theID = analyze_imdbid(d['movieID'])
        if theID is None:
            continue
        theID = str(theID)
        if theID in seenIDs:
            continue
        seenIDs.append(theID)
        minfo = analyze_title(d['title'])
        try: minfo[self.ranktext] = int(d[self.ranktext].replace('.', ''))
        except: pass
        [IF_MASK]
            try: minfo['votes'] = int(d['votes'].replace(',', ''))
            except: pass
        if 'rating' in d:
            try: minfo['rating'] = float(d['rating'])
            except: pass
        mlist.append((theID, minfo))
    return mlist

