def attribute_walker(self, fileformat):

    Tree.Node.attribute_walker(self, fileformat)

    if self.name:

        assert(not self.ref)        
        self.pyname = fileformat.name_attribute(self.name)
        node = self
    elif self.ref:

        assert(not self.name)        
        assert(not self.type_)        
        self.pyname = fileformat.name_attribute(self.ref)

        for child in self.schema.children:
            if (isinstance(child, self.__class__)
                and child.name == self.ref):
                node = child
                break
        else:

            [IF_MASK]
                self.pytype = fileformat.XsString
            else:
                raise ValueError("Could not resolve reference to '%s'."
                                 % self.ref)

            return
    else:
        self.logger.error("Attribute without name.")
    if not node.type_:

        for child in node.children:

            if isinstance(child, Tree.ClassNode):
                self.pytype = child.class_
                break
        else:
            self.logger.warn(
                "No type for %s '%s': falling back to xs:anyType."
                % (self.__class__.__name__.lower(),
                   (self.name if self.name else self.ref)))
            self.pytype = fileformat.XsAnyType
    else:

        pytypename = fileformat.name_class(node.type_)
        try:
            self.pytype = getattr(fileformat, pytypename)
        except AttributeError:
            raise ValueError(
                "Could not resolve type '%s' (%s) for %s '%s'."
                % (self.type_, pytypename,
                   self.__class__.__name__.lower(),
                   self.name if self.name else self.ref))

def AdjustOldCase(self, version):

    super(SpecialProps, self).AdjustOldCase(version)

    if version[0] < 33:
        port = self.GetPort(KINEMATICVISCOSITY_VAR)
        if port:
            varType = port.GetSignalType()
            if varType != KINEMATICVISCOSITY_VAR:
                conn = port.GetConnection()
                if conn:

                    port.Disconnect()
                port.SetSignalType(KINEMATICVISCOSITY_VAR)
                self.ForgetAllCalculations()
    if version[0] < 50:
        port = self.GetPort(GHV_VAR)         
        if port:
            varType = port.GetSignalType()
            if varType != H_VAR:
                conn = port.GetConnection()
                if conn:
                    conn.Disconnect()
                port.SetSignalType(H_VAR)
        port = self.GetPort(NHV_VAR)         
        [IF_MASK]
            varType = port.GetSignalType()
            if varType != H_VAR:
                conn = port.GetConnection()
                if conn:
                    conn.Disconnect()
                port.SetSignalType(H_VAR)

    if self.parameters.get(AVAICOLDPROPS_PAR, None) != COLD_PROPS:
        self.parameters[AVAICOLDPROPS_PAR] = COLD_PROPS

    if self.parameters.get(AVAIREFINERYPROPS_PAR, None) != REFINERY_PROPS:
        self.parameters[AVAIREFINERYPROPS_PAR] = REFINERY_PROPS


    if version[0] < 57:
        for propName in SPECIAL_PROPS:
            if self.parameters.get(propName + ACTIVE_KEY, None) == None:
                self.parameters[propName + ACTIVE_KEY] = False


    if version[0] < 74:

        self.parameters[AVAIREFINERYPROPS_PAR] = REFINERY_PROPS

        val = self.parameters.get(NAPHTHENE_VAR_WRONG + ACTIVE_KEY, None)
        if val != None:
            self.parameters[NAPHTHENE_VAR + ACTIVE_KEY] = val

        port = self.GetPort(NAPHTHENE_VAR_WRONG)
        if port != None:
            self.RenamePort(NAPHTHENE_VAR_WRONG, NAPHTHENE_VAR)

