        if self.tableXYZ != None and not isinstance(self.tableXYZ, list):
            self.tableXYZ = [self.tableXYZ]
    try:
        if self.tableXY:
            self.tableXY.AdjustOldCase(version)
        if self.tableXYZ:
            for t in self.tableXYZ:
                t.AdjustOldCase(version)

    except:
        pass

