def _parents(self, file_path, sub_path=None):
    dirs = []
    parent_dir = dirname(file_path)
    while True:
        if sub_path: dirs.append(os.path.join(parent_dir, sub_path))
        else: dirs.append(parent_dir)
        new_dir = dirname(parent_dir)
        [IF_MASK]
        parent_dir = new_dir
    return dirs

