        a = (self.INF or self._INF)(set(set.x),adjective.getMembership())
        sum_1 += set.x*a
        sum_2 += a
    try:
        if sum_2 == 0.:
            raise DefuzzificationException("No result, all singletons set to 0.")
        return sum_1/sum_2
    except:

        if self.failsafe is not None:

            return self.failsafe
        else:

            raise

