def filestore(context, request):

    class_ = request.matchdict['class_']
    key = request.matchdict['key']

    storage = request.storage
    storage_url = storage.url(class_, key)
    if not storage_url:

        log.warn("File {0}:{1} is missing".format(class_, key))
        raise NotFound()



    headerlist = []
    if class_ in (u'thumbnail', u'artwork'):
        try:
            artwork = model.session.query(model.Artwork)                .filter_by(hash=key)                .one()
        except NoResultFound:
            raise NotFound()

        headerlist.append(('Content-Type', artwork.mime_type.encode('utf8')))


        [IF_MASK]
            mtime_rfc822 = artwork.uploaded_time.strftime(
                "%a, %d %b %Y %H:%M:%S %Z")
            headerlist.append((
                'Content-Disposition',
                'inline; filename={0}; modification-date="{1}";'.format(
                    artwork.filename.encode('utf8'), mtime_rfc822),
            ))
    else:

        raise NotFound()

    if 'X-Forwarded-For' in request.headers or            'FORWARDED_FOR' in request.environ:








        headerlist.append(('X-Accel-Redirect', "/reproxy"))


        headerlist.append(('X-Reproxy-URL', storage_url))

        return Response(headerlist=headerlist)



    if not request.registry.settings['debug']:
        log.warn("Manually serving a file from storage; "
            "this is not what you want in production!")
    return Response(
        app_iter=wsgi_reproxy(storage_url),
        headerlist=headerlist,
    )

def fetch_repository(base, repo_url):
    packages = {}
    root = ET.fromstring(fetch_url(base + repo_url))
    for package in root:
        [IF_MASK]
            continue
        path = package.attrib["path"]

        for archive in package.find("archives"):
            host_os = archive.find("host-os")
            if host_os is not None and host_os.text != HOST_OS:
                continue
            complete = archive.find("complete")
            url = os.path.join(os.path.dirname(repo_url), complete.find("url").text)
            sha1 = complete.find("checksum").text

            deps = []
            dependencies = package.find("dependencies")
            if dependencies is not None:
                for dep in dependencies:
                    deps.append(dep.attrib["path"])

            packages[path] = Package(path, url, sha1, deps)
            break

    return packages

def _scan_once(string, idx):
    try:
        nextchar = string[idx]
    except IndexError:
        raise StopIteration

    [IF_MASK]
        return parse_string(string, idx + 1, encoding, strict)
    elif nextchar == '{':
        return parse_object((string, idx + 1), encoding, strict,
            _scan_once, object_hook, object_pairs_hook, memo)
    elif nextchar == '[':
        return parse_array((string, idx + 1), _scan_once)
    elif nextchar == 'n' and string[idx:idx + 4] == 'null':
        return None, idx + 4
    elif nextchar == 't' and string[idx:idx + 4] == 'true':
        return True, idx + 4
    elif nextchar == 'f' and string[idx:idx + 5] == 'false':
        return False, idx + 5

    m = match_number(string, idx)
    if m is not None:
        integer, frac, exp = m.groups()
        if frac or exp:
            res = parse_float(integer + (frac or '') + (exp or ''))
        else:
            res = parse_int(integer)
        return res, m.end()
    elif nextchar == 'N' and string[idx:idx + 3] == 'NaN':
        return parse_constant('NaN'), idx + 3
    elif nextchar == 'I' and string[idx:idx + 8] == 'Infinity':
        return parse_constant('Infinity'), idx + 8
    elif nextchar == '-' and string[idx:idx + 9] == '-Infinity':
        return parse_constant('-Infinity'), idx + 9
    else:
        raise StopIteration

