def parse_csi(self, s):


    attr = {'key': s[-1], 'flag': '', 'val': 1, 'vals': []}

    if len(s) == 1:
        return attr

    full = s[0:-1]

    if full[0] == '?':
        full = full[1:]
        attr['flag'] = '?'

    if full != '':
        vals = full.split(';')
        for val in vals:

            val = re.sub("\D", "", val)

            if val != '':
                attr['vals'].append(int(val))

    [IF_MASK]
        attr['val'] = int(attr['vals'][0])

    return attr

