def _parse_element(self, element, *args, **kwargs):
    for child in element:
        child_cls = self._xml_application.get_element(child.tag, None)
        if child_cls is not None and issubclass(child_cls, ListElement):
            try:
                value = child_cls.from_element(child, *args, **kwargs)
            except ValidationError:
                pass
            else:
                for basetype in (List, Entry, EntryRef, External):
                    [IF_MASK]
                        break
                else:
                    list.append(self, value)
                    continue
                for elem in self:
                    if isinstance(elem, basetype) and value._xml_id == elem._xml_id:
                        element.remove(child)
                        break
                else:
                    list.append(self, value)

def _add_item(self, value):
    for basetype in (List, Entry, EntryRef, External):
        if isinstance(value, basetype):
            break
    else:
        if isinstance(value, ListElement):
            return value
        raise TypeError("cannot add element type %s to List" % value.__class__.__name__)
    for elem in self:
        [IF_MASK]
            raise ValueError("cannot have more than one %s with the same id attribute at this level: %r" % (basetype.__name__, value._xml_id))
    self._insert_element(value.element)
    return value

def _parse_element(self, element, *args, **kwargs):
    self._lists = {}
    for child in element:
        [IF_MASK]
            try:
                rlist = List.from_element(child, *args, **kwargs)
            except ValidationError:
                pass
            else:
                if rlist.name in self._lists:
                    element.remove(child)
                    continue
                list.append(self, rlist)
                self._lists[rlist.name] = rlist
        else:
            element.remove(child)

def _render_fieldset(self, fieldset, fields, normal_row, help_text_html, errors_on_separate_row):
    output, hidden_fields = [], []

    if fieldset:
        output.append(normal_row%{
            'errors': '',
            'label': '&nbsp;',
            'field': self.fieldset_template%{
                'title': fieldset,
                'section': slugify(fieldset),
                },
            'help_text': '',
            })


    for name in fields:
        field = filter(lambda f: f[0] == name, self.fields.items())[0][1]

        bf = BoundField(self, field, name)
        bf_errors = self.error_class([escape(error) for error in bf.errors])                                      
        [IF_MASK]
            if bf_errors:
                top_errors.extend([u'(Hidden field %s) %s' % (name, force_unicode(e)) for e in bf_errors])
            hidden_fields.append(unicode(bf))
        else:
            if errors_on_separate_row and bf_errors:
                output.append(error_row % force_unicode(bf_errors))
            if bf.label:
                label = escape(force_unicode(bf.label))


                if self.label_suffix:
                    if label[-1] not in ':?.!':
                        label += self.label_suffix
                label = bf.label_tag(label) or ''
            else:
                label = ''
            if field.help_text:
                help_text = help_text_html % force_unicode(field.help_text)
            else:
                help_text = u''
            output.append(normal_row % {
                'errors': force_unicode(bf_errors),
                'label': force_unicode(label),
                'field': unicode(bf),
                'help_text': help_text,
                'field_name': unicode(name),
                })

    return output, hidden_fields

