def DeleteObject(self, obj):



    if isinstance(obj, UnitOperations.OpParameter):
        if obj.GetName() == NUSECTIONS_PAR:
            self.InfoMessage('CantDeleteObject', (obj.GetPath(),), MessageHandler.errorMessage)
            return
        [IF_MASK]
            self.InfoMessage('CantDeleteObject', (obj.GetPath(),), MessageHandler.errorMessage)
            return
        if obj.GetName() == NURXN_PAR:
            self.InfoMessage('CantDeleteObject', (obj.GetPath(),), MessageHandler.errorMessage)
            return

    elif isinstance(obj, EquationSolver.Integrator) and self.integrator is obj:
        if hasattr(self.integrator, 'CleanUp'):
            self.integrator.CleanUp()
        self.integrator = None
        return
    elif isinstance(obj, Ports.Port) and self is obj.GetParent():




        raise SimError('CantDelPortDirectly', (obj.GetPath(), self.GetPath()))

    elif isinstance(obj, ReactorObject):
        try:
            locked = obj.locked
        except AttributeError:
            locked = False

        if locked:
            raise SimError('CannotRemoveLockedObject', obj.GetPath())
        else:
            self.UnlinkObject(obj)
            obj.CleanUp()

    super(PFR, self).DeleteObject(obj)

def parse_basics():
    for fn in glob.glob(STATS_XML % 'people'):
        dom = pulldom.parse(fn)
        for event, node in dom:
            if event == "START_ELEMENT" and node.tagName == "person":
                out = web.storage(node.attributes.items())
                dom.expandNode(node)
                out.roles = map(lambda r: web.storage(r.attributes.items()), node.getElementsByTagName('role'))

                [IF_MASK]
                    out.represents = out.state + '-' + out.district.zfill(2)
                else:
                    if out.get('state'):
                        out.represents = out.state
                        assert out.title == 'Sen.'

                if 'current-committee-assignment' in [
                  hasattr(x, 'tagName') and x.tagName for x in node.childNodes
                ]:
                    out.active = True

                yield out

