def xpath(self):
    path = self.selector.xpath()
    attrib = self._xpath_attrib()
    value = self.value
    if self.operator == 'exists':
        assert not value
        path.add_condition(attrib)
    elif self.operator == '=':
        path.add_condition('%s = %s' % (attrib,
                                        xpath_literal(value)))
