def search(cd, origin, heading, scale, rt):

    history = []
    def probe(r):

        cd[0] = pol2xy(origin, heading, r)
        history.append(cd[0])
        bb1 = bbox(*cd)

        return not any(rt.search(bb1))
    def search3(step, r):
        s2 = step // 2
        [IF_MASK]
            if step < scale:
                return r-s2
            else:
                return search3(s2, r-s2)
        if probe(r + s2):
            step = s2
        else:
            step *= 2
        return search3(step, r + step)
    return search3(scale, scale), history

