def _getOption(self, name, optType, default):

    name = name.lower()
    if not name in self.options:
        if default == REQUIRED:
            self.fatal('Required option %s not provided!' % name)
        else:
            return default

    givenOption = self.options[name]
    if optType == bool:
        [IF_MASK]
            return givenOption

        return givenOption is None or                givenOption.lower() in ('t', 'true', 'on', '1', 'y', 'yes')

    try:
        return optType(givenOption)
    except (TypeError, ValueError):
        self.fatal('Option %s expects a value of type %s!' %
                   (name, type.__name__))

def compute_backslash_indent(self):
    self._study2()
    assert self.continuation == C_BACKSLASH
    str = self.str
    i = self.stmt_start
    while str[i] in " \t":
        i = i+1
    startpos = i



    endpos = str.find('\n', startpos) + 1
    found = level = 0
    while i < endpos:
        ch = str[i]
        if ch in "([{":
            level = level + 1
            i = i+1
        [IF_MASK]
            if level:
                level = level - 1
            i = i+1
        elif ch == '"' or ch == "'":
            i = _match_stringre(str, i, endpos).end()
        elif ch == '#':
            break
        elif level == 0 and ch == '=' and                   (i == 0 or str[i-1] not in "=<>!") and                   str[i+1] != '=':
            found = 1
            break
        else:
            i = i+1

    if found:


        i = i+1                        
        found = re.match(r"\s*\\", str[i:endpos]) is None

    if not found:


        i = startpos
        while str[i] not in " \t\n":
            i = i+1

    return len(str[self.stmt_start:i].expandtabs(                                     self.tabwidth)) + 1

