def relative_time(d, now=None):

    def singplural(singular, plural, c):
        if c == 1: return singular
        else: return plural

    chunks = (        (60 * 60 * 24 * 365, lambda n: singplural('year', 'years', n)),        (60 * 60 * 24 * 30, lambda n: singplural('month', 'months', n)),        (60 * 60 * 24 * 7, lambda n : singplural('week', 'weeks', n)),        (60 * 60 * 24, lambda n : singplural('day', 'days', n)),        (60 * 60, lambda n: singplural('hour', 'hours', n)),        (60, lambda n: singplural('minute', 'minutes', n))    )

    if d and not isinstance(d,datetime):
        now = datetime(d.year, d.month, d.day)
    if now and not isinstance(now, datetime):
        now = datetime(now.year, now.month, now.day)
    [IF_MASK]
        if d.tzinfo:
            now = datetime.now(d.tzinfo)
        else:
            now = datetime.now()

    delta = now - (d - timedelta(0, 0, d.microsecond))
    since = delta.days * 24 * 60 * 60 + delta.seconds

    if since <= 0:
        return u'just now'

    for i, (seconds, name) in enumerate(chunks):
        count = since // seconds
        if count != 0:
            break
    s = '%(number)d %(type)s ago' % {'number': count, 'type':name(count)}
    return s

def _get_srl_spans(self, grid):

    [IF_MASK]
        predicates = self._get_column(grid, self._colmap['srl']+1)
        start_col = self._colmap['srl']+2
    else:
        predicates = self._get_column(grid, self._colmap['srl'])
        start_col = self._colmap['srl']+1



    num_preds = len([p for p in predicates if p != '-'])

    spanlists = []
    for i in range(num_preds):
        col = self._get_column(grid, start_col+i)
        spanlist = []
        stack = []
        for wordnum, srl_tag in enumerate(col):
            (left, right) = srl_tag.split('*')
            for tag in left.split('('):
                if tag:
                    stack.append((tag, wordnum))
            for i in range(right.count(')')):
                (tag, start) = stack.pop()
                spanlist.append( ((start, wordnum+1), tag) )
        spanlists.append(spanlist)

    return spanlists

