def read_until(q, pattern, timeout=1000):
    import re
    start = millis()
    lines = []
    pat = re.compile(pattern)
    found = False
    while millis() - start < timeout:
        try:
            line = q.get(timeout=.2)
            lines.append(line)
            [IF_MASK]
                found = True
                break
        except Empty:
            pass
    return (found, lines)

def _innerDrawLabel(self, sty, radius, cx, cy, angle, car, sar, labelClass=StrandLabel):

    fmt = sty.format
    value = radius*self._norm
    if not fmt:
        text = None
    elif isinstance(fmt,str):
        [IF_MASK]
            text = sty._text
        else:
            text = fmt % value
    elif callable(fmt):
        text = fmt(value)
    else:
        raise ValueError("Unknown formatter type %s, expected string or function" % fmt)

    if text:
        dR = sty.dR
        if dR:
            radius += dR/self._radius
        L = _setupLabel(labelClass, text, radius, cx, cy, angle, car, sar, sty)
        if dR<0: L._anti = 1
    else:
        L = None
    return L

