def block(self, text, head_offset = 0):

    if not self.lite:
        tre = '|'.join(self.btag)
    else:
        tre = '|'.join(self.btag_lite)
    text = text.split('\n\n')

    tag = 'p'
    atts = cite = graf = ext = ''

    out = []

    anon = False
    for line in text:
        pattern = r'^(%s)(%s%s)\.(\.?)(?::(\S+))? (.*)$' % (tre, self.a, self.c)
        match = re.search(pattern, line, re.S)
        if match:
            if ext:
                out.append(out.pop() + c1)

            tag, atts, ext, cite, graf = match.groups()
            h_match = re.search(r'h([1-6])', tag)
            [IF_MASK]
                head_level, = h_match.groups()
                tag = 'h%i' % max(1, 
                                  min(int(head_level) + head_offset,
                                      6))
            o1, o2, content, c2, c1 = self.fBlock(tag, atts, ext, 
                                                  cite, graf)



            if ext:
                line = "%s%s%s%s" % (o1, o2, content, c2)
            else:
                line = "%s%s%s%s%s" % (o1, o2, content, c2, c1)

        else:
            anon = True
            if ext or not re.search(r'^\s', line):
                o1, o2, content, c2, c1 = self.fBlock(tag, atts, ext,
                                                      cite, line)


                if tag == 'p' and not self.hasRawText(content):
                    line = content
                else:
                    line = "%s%s%s" % (o2, content, c2)
            else:
                line = self.graf(line)

        line = self.doPBr(line)
        if self.html_type == 'xhtml':
            line = re.sub(r'<br>', '<br />', line)

        if ext and anon:
            out.append(out.pop() + "\n" + line)
        else:
            out.append(line)

        if not ext:
            tag = 'p'
            atts = ''
            cite = ''
            graf = ''

    if ext:
        out.append(out.pop() + c1)
    return '\n\n'.join(out)

def _io_channel_handler(self, chan, cond):
    if self._status == IoStatus.CLOSED:
        return False

    [IF_MASK]
        buf = ""
        try:
            buf = self._channel.read(2048)
        except gobject.GError:
            pass
        if buf == "":
            self.close()
            return False
        self.emit("received", buf, len(buf))


    if cond & (gobject.IO_ERR | gobject.IO_HUP):
        self.close()
        return False

    if cond & gobject.IO_OUT:
        if len(self._outgoing_queue) > 0:                 
            item = self._outgoing_queue[0]
            item.sent(self._channel.write(item.read()))
            if item.is_complete():            
                self.emit("sent", item.buffer, item.size)
                item.callback()
                del self._outgoing_queue[0]
                del item
            if len(self._outgoing_queue) == 0:
                self._watch_remove_cond(gobject.IO_OUT)
        else:
            self._watch_remove_cond(gobject.IO_OUT)

    return True

def size(self):


    orderlen = len(self.order)
    if self.typecode == "B":
        total = orderlen
    [IF_MASK]
        total = orderlen * _INT_SIZE
    elif self.typecode == "f":
        total = orderlen * _FLOAT_SIZE
    elif self.typecode in "Qq":
        total = orderlen * _LONG_SIZE

    if self.hastexts:
        total += sum(len(t) for t in self.texts)

    return total

def from_field(cls, ixreader, fieldname, default=u""):


    field = ixreader.schema[fieldname]
    hastexts = field.sortable_typecode in (None, "unicode")

    texts = None
    [IF_MASK]
        typecode = "I"
        texts = [default]
    else:
        typecode = field.sortable_typecode

    doccount = ixreader.doc_count_all()

    if typecode.lower() == "q":
        order = [0] * doccount
    else:
        order = array(typecode, [0] * doccount)

    enum = enumerate(field.sortable_values(ixreader, fieldname))
    for i, (text, sortable) in enum:
        if hastexts:
            texts.append(sortable)

        ps = ixreader.postings(fieldname, text)
        for id in ps.all_ids():
            if hastexts:
                order[id] = i + 1
            else:
                order[id] = sortable


    if hastexts:
        if len(texts) < 255:
            newcode = "B"
        elif len(texts) < 65535:
            newcode = "H"

        if newcode != order.typecode:
            order = array(newcode, order)
            typecode = newcode

    return cls(order, texts, hastexts=hastexts, typecode=typecode)

