    for bit in bits[1:]:
        if bit[:2] == 'fI':
            self.write('<em>' + escape(bit[2:]))
            self.state = 'em'
        elif bit[:2] == 'fB':
            self.write('<strong>' + escape(bit[2:]))
            self.state = 'strong'
        elif bit[:2] == 'fR':
            self.write('</%s>' % self.state)
            self.write(escape(bit[2:]))
            self.state = 'regular'
        elif bit[:2] == 'fU':


            self.write('<u>' + escape(bit[2:]))
            self.state = 'u'
        elif bit[:3] == '(co':
            self.write('&copy;' + escape(bit[3:]))
        else:
            self.write(escape(bit))

    if self.tp == 1:
        self.write('</dt>')
        self.tp = 2
    elif self.tp == 2:
        self.tp = 3

