def _extractall(self, path=".", members=None):

    import copy
    import operator
    from tarfile import ExtractError
    directories = []

    [IF_MASK]
        members = self

    for tarinfo in members:
        if tarinfo.isdir():

            directories.append(tarinfo)
            tarinfo = copy.copy(tarinfo)
            tarinfo.mode = 448                       
