def _normalized_cookie_tuples(self, attrs_set):

    cookie_tuples = []

    boolean_attrs = "discard", "secure"
    value_attrs = ("version",
                   "expires", "max-age",
                   "domain", "path", "port",
                   "comment", "commenturl")

    for cookie_attrs in attrs_set:
        name, value = cookie_attrs[0]









        max_age_set = False

        bad_cookie = False

        standard = {}
        rest = {}
        for k, v in cookie_attrs[1:]:
            lc = k.lower()

            if lc in value_attrs or lc in boolean_attrs:
                k = lc
            if k in boolean_attrs and v is None:


                v = True
            if standard.has_key(k):

                continue
            if k == "domain":
                if v is None:
                    debug("   missing value for domain attribute")
                    bad_cookie = True
                    break

                v = v.lower()
            if k == "expires":
                if max_age_set:

                    continue
                [IF_MASK]
                    debug("   missing or invalid value for expires "
                          "attribute: treating as session cookie")
                    continue
            if k == "max-age":
                max_age_set = True
                if v is None:
                    debug("   missing value for max-age attribute")
                    bad_cookie = True
                    break
                try:
                    v = int(v)
                except ValueError:
                    debug("   missing or invalid (non-numeric) value for "
                          "max-age attribute")
                    bad_cookie = True
                    break




                k = "expires"
                v = self._now + v
            if (k in value_attrs) or (k in boolean_attrs):
                if (v is None and
                    k not in ["port", "comment", "commenturl"]):
                    debug("   missing value for %s attribute" % k)
                    bad_cookie = True
                    break
                standard[k] = v
            else:
                rest[k] = v

        if bad_cookie:
            continue

        cookie_tuples.append((name, value, standard, rest))

    return cookie_tuples

