def check_peers(message):
    if type(message) != dict:
        raise BTFailure
    if message.has_key('failure reason'):
        if type(message['failure reason']) != str:
            raise BTFailure('non-text failure reason')
        return
    if message.has_key('warning message'):
        if type(message['warning message']) != str:
            raise BTFailure('non-text warning message')
    peers = message.get('peers', [])
    if type(peers) != list:
        raise BTFailure('invalid peer list')
    for p in peers:
        if type(p) != dict:
            raise BTFailure('invalid entry in peer list')
        [IF_MASK]
            raise BTFailure('invalid entry in peer list')
        port = p.get('port')
        if type(port) not in ints or p <= 0:
            raise BTFailure('invalid entry in peer list')
        if p.has_key('nid'):
            nid = p.get('nid')
            if type(nid) != str or len(nid) != 1:
                raise BTFailure('invalid entry in peer list')





    interval = message.get('interval', 1)
    if type(interval) not in ints or interval <= 0:
        raise BTFailure('invalid announce interval')
    minint = message.get('min interval', 1)
    if type(minint) not in ints or minint <= 0:
        raise BTFailure('invalid min announce interval')
    tcodes = message.get('tracking codes', [])
    if type(tcodes) != list:
        raise BTFailure('invalid tracking code list')
    for t in tcodes:
        if type(t) != list:
            raise BTFailure('invalid entry in tracking code list')
        if len(t) != 2:
            raise BTFailure('invalid tracking code entry length')
        if type(t[0]) != str or type(t[1]) != str:
            raise BTFailure('invalid format for tracking code components')

def get_auth(auth_host, auth_port, auth_url, user_name, user_key, tenant_name):

    conn = httplib.HTTPConnection(auth_host, auth_port)

    headers = {'Accept': 'application/json',
               'Content-Type': 'application/json'}
    body = {}
    body['auth'] = {
        "passwordCredentials": {
            "username": user_name,
            "password": user_key,
        },
        "tenantName": tenant_name
    }
    conn.request('POST', auth_url,
                 json.dumps(body, indent=2), headers)

    res = conn.getresponse()
    [IF_MASK]
        raise Exception('The authentication has failed')

    data = res.read()
    body = json.loads(data)
    token = body.get('access').get('token').get('id')
    tenant_id = body.get('access').get('token').get('tenant').get('id')
    return token, tenant_id

def getTrackPoints(self):

    laps = []
    _ns = self._ns

    track_segs = self._xml.findall(_ns('NS-trk/NS-trkseg'))
    log_segs = self._xml.findall(_ns('NS-extensions/NS-ssrlog/NS-logseg'))
    recorded_laps = self._getLaps()

    lap = []

    for track_seg, log_seg in zip(track_segs, log_segs):

        track_points = track_seg.findall(_ns('NS-trkpt'))
        log_points = log_seg.findall(_ns('NS-logpt'))



        if len(track_points) == 0:






            [IF_MASK]
                lap.append(None)
            continue


        while track_points or log_points:

            point = {}

            track_point, log_point = self._getPoints(track_points, log_points)

            if track_point is not None:
                p = track_point
                point['lat'] = float(p.get('lat'))
                point['lon'] = float(p.get('lon'))
                point['ele'] = float(p.find(_ns('NS-ele')).text)
                point['time'] = p.find(_ns('NS-time')).text


            if log_point is not None:

                p = log_point

                point['time'] = p.get('time')

                spd = p.find(_ns('NS-spd'))
                if spd is not None:
                    point['spd'] = float(spd.text)

                tmp = p.find(_ns('NS-tmp'))
                if tmp is not None:
                    point['tmp'] = float(tmp.text)

                brm = p.find(_ns('NS-brm'))
                if brm is not None:
                    point['brm'] = float(brm.text)

                hrm = p.find(_ns('NS-hrm'))
                if hrm is not None:
                    point['hrm'] = int(float(hrm.text))

                cad = p.find(_ns('NS-cad'))
                if cad is not None:
                    point['cad'] = int(float(cad.text))

                pwr = p.find(_ns('NS-pwr'))
                if pwr is not None:
                    point['pwr'] = int(float(pwr.text))


            if recorded_laps and recorded_laps[0]['end'] < point['time']:
                rec_lap = recorded_laps.pop(0)
                rec_lap['track_points'] = lap
                laps.append(rec_lap)
                lap = []

            lap.append(point)





        lap.append(None)


    if lap:
        lap.pop()                   


    if len(laps) > 0 and lap:

        if len(lap) > 5:
            laps.append(self._generateLastLap(laps, lap))
        else:


            laps[-1]['track_points'].extend(lap)

    elif lap:
        l = self.getSummary()
        l['track_points'] = lap

        laps.append(l)


    for lap in laps:
        self._mergePoints(lap)



    return laps

def combineQualities(anyQualities, bestQualities):
    anyQuality = 0
    bestQuality = 0
    [IF_MASK]
        anyQuality = reduce(operator.or_, anyQualities)
    if bestQualities:
        bestQuality = reduce(operator.or_, bestQualities)
    return anyQuality | (bestQuality<<16)

