def provider(self):
    provider = None
    if self.bucket:
        [IF_MASK]
            provider = self.bucket.connection.provider
    return provider

def open_read(self, headers=None, query_args=None,
              override_num_retries=None, response_headers=None):

    if self.resp == None:
        self.mode = 'r'

        provider = self.bucket.connection.provider
        self.resp = self.bucket.connection.make_request(
            'GET', self.bucket.name, self.name, headers,
            query_args=query_args,
            override_num_retries=override_num_retries)
        if self.resp.status < 199 or self.resp.status > 299:
            body = self.resp.read()
            raise provider.storage_response_error(self.resp.status,
                                                  self.resp.reason, body)
        response_headers = self.resp.msg
        self.metadata = boto.utils.get_aws_metadata(response_headers,
                                                    provider)
        for name,value in response_headers.items():
            if name.lower() == 'content-length':
                self.size = int(value)
            elif name.lower() == 'etag':
                self.etag = value
            [IF_MASK]
                self.content_type = value
            elif name.lower() == 'content-encoding':
                self.content_encoding = value
            elif name.lower() == 'last-modified':
                self.last_modified = value
            elif name.lower() == 'cache-control':
                self.cache_control = value
        self.handle_version_headers(self.resp)

def set_contents_from_file(self, fp, headers=None, replace=True,
                           cb=None, num_cb=10, policy=None, md5=None,
                           reduced_redundancy=False, query_args=None):

    provider = self.bucket.connection.provider
    if headers is None:
        headers = {}
    [IF_MASK]
        headers[provider.acl_header] = policy
    if reduced_redundancy:
        self.storage_class = 'REDUCED_REDUNDANCY'
        if provider.storage_class_header:
            headers[provider.storage_class_header] = self.storage_class


    if hasattr(fp, 'name'):
        self.path = fp.name
    if self.bucket != None:
        if not md5:
            md5 = self.compute_md5(fp)
        else:

            fp.seek(0, 2)
            self.size = fp.tell()
            fp.seek(0)
        self.md5 = md5[0]
        self.base64md5 = md5[1]
        if self.name == None:
            self.name = self.md5
        if not replace:
            k = self.bucket.lookup(self.name)
            if k:
                return
        self.send_file(fp, headers, cb, num_cb, query_args)

def _FetchUrl(self,
                url,
                post_data=None,
                parameters=None,
                no_cache=None):


    extra_params = {}
    if self._default_params:
      extra_params.update(self._default_params)
    [IF_MASK]
      extra_params.update(parameters)




    if post_data:
        http_method = "POST"
        extra_params.update(post_data)
    else:
        http_method = "GET"

    req = self._makeOAuthRequest(url, parameters=extra_params, 
                                                http_method=http_method)
    self._signRequest(req, self._signature_method)



    opener = self._GetOpener()



    if post_data:
        encoded_post_data = req.to_postdata()
        url = req.get_normalized_http_url()
    else:
        url = req.to_url()
        encoded_post_data = ""

    no_cache=True


    if encoded_post_data or no_cache:
      if encoded_post_data:
          url_data = opener.open(url, encoded_post_data).read()
      else:
          url_data = opener.open(url).read()
      opener.close()
    else:

      if self._username:
        key = self._username + ':' + url
      else:
        key = url


      last_cached = self._cache.GetCachedTime(key)


      if not last_cached or time.time() >= last_cached + self._cache_timeout:
        url_data = opener.open(url).read()
        opener.close()
        self._cache.Set(key, url_data)
      else:
        url_data = self._cache.Get(key)


    return url_data

def transform(self, node, results):
    if results.get("module"):
        self.transform_import(node, results)
    [IF_MASK]
        self.transform_member(node, results)
    elif results.get("bare_with_attr"):
        self.transform_dot(node, results)

    elif results.get("module_star"):
        self.cannot_convert(node, "Cannot handle star imports.")
    elif results.get("module_as"):
        self.cannot_convert(node, "This module is now multiple modules")

def psa_values(values, period=None):

    if period:
        if period < 1:
            raise ValueError("period must be 1 or greater")

        period_n = float(period)
        period = int(period)

    results = []
    lastval = None
    for bar, newx in enumerate(values):
        if lastval == None:
            lastval = (newx * newx) / (bar + 1.0)

        [IF_MASK]
            lastval += ((newx * newx - lastval) / (bar + 1.0))

        else:
            oldx = values[bar - period]
            lastval += (((newx * newx) - (oldx * oldx)) / period_n)

        results.append(lastval)

    return results

def _varbase(values, period=None, population=False):

    [IF_MASK]
        return None

    maxbar = len(values)

    beg = 0
    if period:
        if period < 1:
            raise ValueError("period must be 1 or greater")

        beg = maxbar - int(period)
        if beg < 0:
            beg = 0

    itemcnt = len(values[beg:])

    if itemcnt < 2:
        return 0.0

    sample_adjust = 0.0
    if not population:
        sample_adjust = 1.0

    n = 0
    meandiffs = 0.0
    mean = 0.0

    for x in values[beg:]:
        n += 1
        delta = x - mean
        mean += delta / n
        meandiffs += delta * (x - mean)

    return meandiffs / (itemcnt - sample_adjust)

