def need_more_events(self):
    if not self.events:
        return True
    event = self.events[0]
    [IF_MASK]
        return self.need_events(1)
    elif isinstance(event, SequenceStartEvent):
        return self.need_events(2)
    elif isinstance(event, MappingStartEvent):
        return self.need_events(3)
    else:
        return False

def expect_node(self, root=False, sequence=False, mapping=False,
        simple_key=False):
    self.root_context = root
    self.sequence_context = sequence
    self.mapping_context = mapping
    self.simple_key_context = simple_key
    if isinstance(self.event, AliasEvent):
        self.expect_alias()
    elif isinstance(self.event, (ScalarEvent, CollectionStartEvent)):
        self.process_anchor(u'&')
        self.process_tag()
        if isinstance(self.event, ScalarEvent):
            self.expect_scalar()
        elif isinstance(self.event, SequenceStartEvent):
            if self.flow_level or self.canonical or self.event.flow_style                        or self.check_empty_sequence():
                self.expect_flow_sequence()
            else:
                self.expect_block_sequence()
        elif isinstance(self.event, MappingStartEvent):
            [IF_MASK]
                self.expect_flow_mapping()
            else:
                self.expect_block_mapping()
    else:
        raise EmitterError("expected NodeEvent, but got %s" % self.event)

def expect_flow_mapping_key(self):
    if isinstance(self.event, MappingEndEvent):
        self.indent = self.indents.pop()
        self.flow_level -= 1
        if self.canonical:
            self.write_indicator(u',', False)
            self.write_indent()
        self.write_indicator(u'}', False)
        self.state = self.states.pop()
    else:
        self.write_indicator(u',', False)
        [IF_MASK]
            self.write_indent()
        if not self.canonical and self.check_simple_key():
            self.states.append(self.expect_flow_mapping_simple_value)
            self.expect_node(mapping=True, simple_key=True)
        else:
            self.write_indicator(u'?', True)
            self.states.append(self.expect_flow_mapping_value)
            self.expect_node(mapping=True)

def check_simple_key(self):
    length = 0
    if isinstance(self.event, NodeEvent) and self.event.anchor is not None:
        [IF_MASK]
            self.prepared_anchor = self.prepare_anchor(self.event.anchor)
        length += len(self.prepared_anchor)
    if isinstance(self.event, (ScalarEvent, CollectionStartEvent))                and self.event.tag is not None:
        if self.prepared_tag is None:
            self.prepared_tag = self.prepare_tag(self.event.tag)
        length += len(self.prepared_tag)
    if isinstance(self.event, ScalarEvent):
        if self.analysis is None:
            self.analysis = self.analyze_scalar(self.event.value)
        length += len(self.analysis.scalar)
    return (length < 128 and (isinstance(self.event, AliasEvent)
        or (isinstance(self.event, ScalarEvent)
                and not self.analysis.empty and not self.analysis.multiline)
        or self.check_empty_sequence() or self.check_empty_mapping()))

def process_scalar(self):
    if self.analysis is None:
        self.analysis = self.analyze_scalar(self.event.value)
    if self.style is None:
        self.style = self.choose_scalar_style()
    split = (not self.simple_key_context)



    if self.style == '"':
        self.write_double_quoted(self.analysis.scalar, split)
    elif self.style == '\'':
        self.write_single_quoted(self.analysis.scalar, split)
    elif self.style == '>':
        self.write_folded(self.analysis.scalar)
    [IF_MASK]
        self.write_literal(self.analysis.scalar)
    else:
        self.write_plain(self.analysis.scalar, split)
    self.analysis = None
    self.style = None

def analyze_scalar(self, scalar):


    if not scalar:
        return ScalarAnalysis(scalar=scalar, empty=True, multiline=False,
                allow_flow_plain=False, allow_block_plain=True,
                allow_single_quoted=True, allow_double_quoted=True,
                allow_block=False)


    block_indicators = False
    flow_indicators = False
    line_breaks = False
    special_characters = False


    leading_space = False
    leading_break = False
    trailing_space = False
    trailing_break = False
    break_space = False
    space_break = False


    if scalar.startswith(u'---') or scalar.startswith(u'...'):
        block_indicators = True
        flow_indicators = True


    preceeded_by_whitespace = True


    followed_by_whitespace = (len(scalar) == 1 or
            scalar[1] in u'\0 \t\r\n\x85\u2028\u2029')


    previous_space = False


    previous_break = False

    index = 0
    while index < len(scalar):
        ch = scalar[index]


        [IF_MASK]

            if ch in u'#,[]{}&*!|>\'\"%@`': 
                flow_indicators = True
                block_indicators = True
            if ch in u'?:':
                flow_indicators = True
                if followed_by_whitespace:
                    block_indicators = True
            if ch == u'-' and followed_by_whitespace:
                flow_indicators = True
                block_indicators = True
        else:

            if ch in u',?[]{}':
                flow_indicators = True
            if ch == u':':
                flow_indicators = True
                if followed_by_whitespace:
                    block_indicators = True
            if ch == u'#' and preceeded_by_whitespace:
                flow_indicators = True
                block_indicators = True


        if ch in u'\n\x85\u2028\u2029':
            line_breaks = True
        if not (ch == u'\n' or u'\x20' <= ch <= u'\x7E'):
            if (ch == u'\x85' or u'\xA0' <= ch <= u'\uD7FF'
                    or u'\uE000' <= ch <= u'\uFFFD') and ch != u'\uFEFF':
                unicode_characters = True
                if not self.allow_unicode:
                    special_characters = True
            else:
                special_characters = True


        if ch == u' ':
            if index == 0:
                leading_space = True
            if index == len(scalar)-1:
                trailing_space = True
            if previous_break:
                break_space = True
            previous_space = True
            previous_break = False
        elif ch in u'\n\x85\u2028\u2029':
            if index == 0:
                leading_break = True
            if index == len(scalar)-1:
                trailing_break = True
            if previous_space:
                space_break = True
            previous_space = False
            previous_break = True
        else:
            previous_space = False
            previous_break = False


        index += 1
        preceeded_by_whitespace = (ch in u'\0 \t\r\n\x85\u2028\u2029')
        followed_by_whitespace = (index+1 >= len(scalar) or
                scalar[index+1] in u'\0 \t\r\n\x85\u2028\u2029')


    allow_flow_plain = True
    allow_block_plain = True
    allow_single_quoted = True
    allow_double_quoted = True
    allow_block = True


    if (leading_space or leading_break
            or trailing_space or trailing_break):
        allow_flow_plain = allow_block_plain = False


    if trailing_space:
        allow_block = False



    if break_space:
        allow_flow_plain = allow_block_plain = allow_single_quoted = False



    if space_break or special_characters:
        allow_flow_plain = allow_block_plain =            allow_single_quoted = allow_block = False



    if line_breaks:
        allow_flow_plain = allow_block_plain = False


    if flow_indicators:
        allow_flow_plain = False


    if block_indicators:
        allow_block_plain = False

    return ScalarAnalysis(scalar=scalar,
            empty=False, multiline=line_breaks,
            allow_flow_plain=allow_flow_plain,
            allow_block_plain=allow_block_plain,
            allow_single_quoted=allow_single_quoted,
            allow_double_quoted=allow_double_quoted,
            allow_block=allow_block)

def write_folded(self, text):
    hints = self.determine_block_hints(text)
    self.write_indicator(u'>'+hints, True)
    if hints[-1:] == u'+':
        self.open_ended = True
    self.write_line_break()
    leading_space = True
    spaces = False
    breaks = True
    start = end = 0
    while end <= len(text):
        ch = None
        if end < len(text):
            ch = text[end]
        if breaks:
            if ch is None or ch not in u'\n\x85\u2028\u2029':
                if not leading_space and ch is not None and ch != u' '                            and text[start] == u'\n':
                    self.write_line_break()
                leading_space = (ch == u' ')
                for br in text[start:end]:
                    if br == u'\n':
                        self.write_line_break()
                    else:
                        self.write_line_break(br)
                if ch is not None:
                    self.write_indent()
                start = end
        [IF_MASK]
            if ch != u' ':
                if start+1 == end and self.column > self.best_width:
                    self.write_indent()
                else:
                    data = text[start:end]
                    self.column += len(data)
                    if self.encoding:
                        data = data.encode(self.encoding)
                    self.stream.write(data)
                start = end
        else:
            if ch is None or ch in u' \n\x85\u2028\u2029':
                data = text[start:end]
                self.column += len(data)
                if self.encoding:
                    data = data.encode(self.encoding)
                self.stream.write(data)
                if ch is None:
                    self.write_line_break()
                start = end
        if ch is not None:
            breaks = (ch in u'\n\x85\u2028\u2029')
            spaces = (ch == u' ')
        end += 1

