def getValue(self,variable):

    try:
        temp = self.accumulate(variable)


        table = list(self.value_table(temp))

        if len(table) == 0:
            raise DefuzzificationException("no value calculable: complete undefined set")

        table.reverse()

        y = table[0][1]
        x = float('+inf')                                          

        for (x_,y_) in table[1:]:
            if y_ > y:
                y = y_
                x = x_
            else:
                break

        return x
    except:

        [IF_MASK]

            return self.failsafe
        else:
            raise

def _serialize_html(write, elem, encoding, qnames, namespaces):
    tag = elem.tag
    text = elem.text
    if tag is Comment:
        write("<!--%s-->" % _escape_cdata(text, encoding))
    elif tag is ProcessingInstruction:
        write("<?%s?>" % _escape_cdata(text, encoding))
    else:
        tag = qnames[tag]
        [IF_MASK]
            if text:
                write(_escape_cdata(text, encoding))
            for e in elem:
                _serialize_html(write, e, encoding, qnames, None)
        else:
            write("<" + tag)
            items = elem.items()
            if items or namespaces:
                items.sort()                
                for k, v in items:
                    if isinstance(k, QName):
                        k = k.text
                    if isinstance(v, QName):
                        v = qnames[v.text]
                    else:
                        v = _escape_attrib_html(v, encoding)

                    write(" %s=\"%s\"" % (qnames[k], v))
                if namespaces:
                    items = namespaces.items()
                    items.sort(key=lambda x: x[1])                 
                    for v, k in items:
                        if k:
                            k = ":" + k
                        write(" xmlns%s=\"%s\"" % (
                            k.encode(encoding),
                            _escape_attrib(v, encoding)
                            ))
            write(">")
            tag = tag.lower()
            if text:
                if tag == "script" or tag == "style":
                    write(_encode(text, encoding))
                else:
                    write(_escape_cdata(text, encoding))
            for e in elem:
                _serialize_html(write, e, encoding, qnames, None)
            if tag not in HTML_EMPTY:
                write("</" + tag + ">")
    if elem.tail:
        write(_escape_cdata(elem.tail, encoding))

def make_info(file_to_torrent, piece_len_exp=None, get_hash=None):

    piece_length = calculate_piece_length(file_to_torrent, piece_len_exp) 
    if get_hash is None:
        get_hash = {}

    if not 'md5' in get_hash:
        get_hash['md5'] = False
    if not 'crc32' in get_hash:
        get_hash['crc32'] = False
    [IF_MASK]
        get_hash['sha1'] = False

    fs_encoding = _get_fs_encoding()
    file_to_torrent = abspath(file_to_torrent)
    pieces = []
    if isdir(file_to_torrent):                
        subs = _subfiles(file_to_torrent)
        subs.sort()
        sh = hashlib.sha1()
        done = 0
        fs = []
        totalsize = 0.0
        totalhashed = 0
        for p, f in subs:
            totalsize += getsize(f)

        for p, f in subs:
            pos = 0
            size = getsize(f)
            h = open(f, 'rb')

            if get_hash['md5']:
                hash_md5 = hashlib.md5()
            if get_hash['sha1']:
                hash_sha1 = hashlib.sha1()
            if get_hash['crc32']:
                hash_crc32 = zlib.crc32('')

            while pos < size:
                a = min(size-pos, piece_length-done)
                readpiece = h.read(a)
                sh.update(readpiece)
                if get_hash['md5']:                
                    hash_md5.update(readpiece)
                if get_hash['crc32']:                
                    hash_crc32 = zlib.crc32(readpiece, hash_crc32)
                if get_hash['sha1']:                
                    hash_sha1.update(readpiece)

                done += a
                pos += a
                totalhashed += a

                if done == piece_length:
                    pieces.append(sh.digest())
                    done = 0
                    sh = hashlib.sha1()

            newdict = {'length': size,
                       'path': _uniconvertl(p, fs_encoding) }
            if get_hash['md5']:
                newdict['md5sum'] = hash_md5.hexdigest()
            if get_hash['crc32']:
                newdict['crc32'] = "%08X" % hash_crc32
            if get_hash['sha1']:
                newdict['sha1'] = hash_sha1.digest()
            fs.append(newdict)
            h.close()
        if done > 0:
            pieces.append(sh.digest())
        return {'pieces': ''.join(pieces), 
                'piece length': piece_length,
                'files': fs, 
                'name': _uniconvert(split(file_to_torrent)[1], fs_encoding) 
               }
    else:              
        size = getsize(file_to_torrent)
        p = 0
        h = open(file_to_torrent, 'rb')

        if get_hash['md5']:
            hash_md5 = hashlib.md5()
        if get_hash['crc32']:
            hash_crc32 = zlib.crc32('')
        if get_hash['sha1']:
            hash_sha1 = hashlib.sha1()

        while p < size:
            x = h.read(min(piece_length, size - p))
            if get_hash['md5']:

                hash_md5.update(x)
            if get_hash['crc32']:

                hash_crc32 = zlib.crc32(x, hash_crc32)
            if get_hash['sha1']:

                hash_sha1.update(x)

            pieces.append(hashlib.sha1(x).digest())
            p += piece_length
            if p > size:
                p = size
        h.close()
        newdict = {'pieces': ''.join(pieces), 
                   'piece length': piece_length,
                   'length': size, 
                   'name': _uniconvert(split(file_to_torrent)[1], fs_encoding),
                  }
        if get_hash['md5']:
            newdict['md5sum'] = hash_md5.hexdigest()
        if get_hash['crc32']:
            newdict['crc32'] = "%08X" % hash_crc32
        if get_hash['sha1']:
            newdict['sha1'] = hash_sha1.digest()

        return newdict

def run(self, doc):
    div = etree.Element("div")
    div.attrib["class"] = "toc"
    last_li = None


    if self.config["title"][0]:
        header = etree.SubElement(div, "span")
        header.attrib["class"] = "toctitle"
        header.text = self.config["title"][0]

    level = 0
    list_stack=[div]
    header_rgx = re.compile("[Hh][123456]")


    used_ids = []
    for c in doc.getiterator():
        if "id" in c.attrib:
            used_ids.append(c.attrib["id"])

    for (p, c) in self.iterparent(doc):
        if not c.text:
            continue








        [IF_MASK]
            for i in range(len(p)):
                if p[i] == c:
                    p[i] = div
                    break

        if header_rgx.match(c.tag):
            tag_level = int(c.tag[-1])





            if tag_level < level:
                list_stack.pop()
                level = tag_level

            if tag_level > level:
                newlist = etree.Element("ul")
                if last_li:
                    last_li.append(newlist)
                else:
                    list_stack[-1].append(newlist)
                list_stack.append(newlist)
                level = tag_level


            if not "id" in c.attrib:
                id = self.config["slugify"][0](c.text)
                if id in used_ids:
                    ctr = 1
                    while "%s_%d" % (id, ctr) in used_ids:
                        ctr += 1
                    id = "%s_%d" % (id, ctr)
                used_ids.append(id)
                c.attrib["id"] = id
            else:
                id = c.attrib["id"]


            last_li = etree.Element("li")
            link = etree.SubElement(last_li, "a")
            link.text = c.text
            link.attrib["href"] = '#' + id

            if int(self.config["anchorlink"][0]):
                anchor = etree.SubElement(c, "a")
                anchor.text = c.text
                anchor.attrib["href"] = "#" + id
                anchor.attrib["class"] = "toclink"
                c.text = ""

            list_stack[-1].append(last_li)

def decorator(caller):

    [IF_MASK]
        return decorator_factory(caller)
    def _decorator(func):                        
        infodict = getinfo(func)
        argnames = infodict['argnames']
        assert not ('_call_' in argnames or '_func_' in argnames), (
            'You cannot use _call_ or _func_ as argument names!')
        src = "lambda %(signature)s: _call_(_func_, %(signature)s)" % infodict

        dec_func = eval(src, dict(_func_=func, _call_=caller))
        return update_wrapper(dec_func, func, infodict)
    return update_wrapper(_decorator, caller)

