        if self.canonical:
            self.write_indicator(',', False)
            self.write_indent()
        self.write_indicator('}', False)
        self.state = self.states.pop()
    else:
        self.write_indicator(',', False)
        if self.canonical or self.column > self.best_width:
            self.write_indent()
        if not self.canonical and self.check_simple_key():
            self.states.append(self.expect_flow_mapping_simple_value)
            self.expect_node(mapping=True, simple_key=True)
        else:
            self.write_indicator('?', True)
            self.states.append(self.expect_flow_mapping_value)
            self.expect_node(mapping=True)

def prepare_tag(self, tag):
    [IF_MASK]
        raise EmitterError("tag must not be empty")
    if tag == '!':
        return tag
    handle = None
    suffix = tag
    prefixes = sorted(self.tag_prefixes.keys())
    for prefix in prefixes:
        if tag.startswith(prefix)                    and (prefix == '!' or len(prefix) < len(tag)):
            handle = self.tag_prefixes[prefix]
            suffix = tag[len(prefix):]
    chunks = []
    start = end = 0
    while end < len(suffix):
        ch = suffix[end]
        if '0' <= ch <= '9' or 'A' <= ch <= 'Z' or 'a' <= ch <= 'z'                    or ch in '-;/?:@&=+$,_.~*\'()[]'                    or (ch == '!' and handle != '!'):
            end += 1
        else:
            if start < end:
                chunks.append(suffix[start:end])
            start = end = end+1
            data = ch.encode('utf-8')
            for ch in data:
                chunks.append('%%%02X' % ord(ch))
    if start < end:
        chunks.append(suffix[start:end])
    suffix_text = ''.join(chunks)
    if handle:
        return '%s%s' % (handle, suffix_text)
    else:
        return '!<%s>' % suffix_text

def write_single_quoted(self, text, split=True):
    self.write_indicator('\'', True)
    spaces = False
    breaks = False
    start = end = 0
    while end <= len(text):
        ch = None
        if end < len(text):
            ch = text[end]
        [IF_MASK]
            if ch is None or ch != ' ':
                if start+1 == end and self.column > self.best_width and split                            and start != 0 and end != len(text):
                    self.write_indent()
                else:
                    data = text[start:end]
                    self.column += len(data)
                    if self.encoding:
                        data = data.encode(self.encoding)
                    self.stream.write(data)
                start = end
        elif breaks:
            if ch is None or ch not in '\n\x85\u2028\u2029':
                if text[start] == '\n':
                    self.write_line_break()
                for br in text[start:end]:
                    if br == '\n':
                        self.write_line_break()
                    else:
                        self.write_line_break(br)
                self.write_indent()
                start = end
        else:
            if ch is None or ch in ' \n\x85\u2028\u2029' or ch == '\'':
                if start < end:
                    data = text[start:end]
                    self.column += len(data)
                    if self.encoding:
                        data = data.encode(self.encoding)
                    self.stream.write(data)
                    start = end
        if ch == '\'':
            data = '\'\''
            self.column += 2
            if self.encoding:
                data = data.encode(self.encoding)
            self.stream.write(data)
            start = end + 1
        if ch is not None:
            spaces = (ch == ' ')
            breaks = (ch in '\n\x85\u2028\u2029')
        end += 1
    self.write_indicator('\'', False)

def determine_block_hints(self, text):
    hints = ''
    if text:
        [IF_MASK]
            hints += str(self.best_indent)
        if text[-1] not in '\n\x85\u2028\u2029':
            hints += '-'
        elif len(text) == 1 or text[-2] in '\n\x85\u2028\u2029':
            hints += '+'
    return hints

def write_folded(self, text):
    hints = self.determine_block_hints(text)
    self.write_indicator('>'+hints, True)
    if hints[-1:] == '+':
        self.open_ended = True
    self.write_line_break()
    leading_space = True
    spaces = False
    breaks = True
    start = end = 0
    while end <= len(text):
        ch = None
        if end < len(text):
            ch = text[end]
        if breaks:
            if ch is None or ch not in '\n\x85\u2028\u2029':
                if not leading_space and ch is not None and ch != ' '                            and text[start] == '\n':
                    self.write_line_break()
                leading_space = (ch == ' ')
                for br in text[start:end]:
                    if br == '\n':
                        self.write_line_break()
                    else:
                        self.write_line_break(br)
                if ch is not None:
                    self.write_indent()
                start = end
        elif spaces:
            [IF_MASK]
                if start+1 == end and self.column > self.best_width:
                    self.write_indent()
                else:
                    data = text[start:end]
                    self.column += len(data)
                    if self.encoding:
                        data = data.encode(self.encoding)
                    self.stream.write(data)
                start = end
        else:
            if ch is None or ch in ' \n\x85\u2028\u2029':
                data = text[start:end]
                self.column += len(data)
                if self.encoding:
                    data = data.encode(self.encoding)
                self.stream.write(data)
                if ch is None:
                    self.write_line_break()
                start = end
        if ch is not None:
            breaks = (ch in '\n\x85\u2028\u2029')
            spaces = (ch == ' ')
        end += 1

def write_plain(self, text, split=True):
    if self.root_context:
        self.open_ended = True
    if not text:
        return
    if not self.whitespace:
        data = ' '
        self.column += len(data)
        if self.encoding:
            data = data.encode(self.encoding)
        self.stream.write(data)
    self.whitespace = False
    self.indention = False
    spaces = False
    breaks = False
    start = end = 0
    while end <= len(text):
        ch = None
        [IF_MASK]
            ch = text[end]
        if spaces:
            if ch != ' ':
                if start+1 == end and self.column > self.best_width and split:
                    self.write_indent()
                    self.whitespace = False
                    self.indention = False
                else:
                    data = text[start:end]
                    self.column += len(data)
                    if self.encoding:
                        data = data.encode(self.encoding)
                    self.stream.write(data)
                start = end
        elif breaks:
            if ch not in '\n\x85\u2028\u2029':
                if text[start] == '\n':
                    self.write_line_break()
                for br in text[start:end]:
                    if br == '\n':
                        self.write_line_break()
                    else:
                        self.write_line_break(br)
                self.write_indent()
                self.whitespace = False
                self.indention = False
                start = end
        else:
            if ch is None or ch in ' \n\x85\u2028\u2029':
                data = text[start:end]
                self.column += len(data)
                if self.encoding:
                    data = data.encode(self.encoding)
                self.stream.write(data)
                start = end
        if ch is not None:
            spaces = (ch == ' ')
            breaks = (ch in '\n\x85\u2028\u2029')
        end += 1

def fullsplit(path, result=None):
    if result is None:
        result = []
    head, tail = os.path.split(path)
    [IF_MASK]
        return [tail] + result
    if head == path:
        return result
    return fullsplit(head, [tail] + result)

