def send_file(self, fp, headers=None, cb=None, num_cb=10):

    def sender(http_conn, method, path, data, headers):
        http_conn.putrequest(method, path)
        for key in headers:
            http_conn.putheader(key, headers[key])
        http_conn.endheaders()
        fp.seek(0)
        save_debug = self.bucket.connection.debug
        self.bucket.connection.debug = 0
        if cb:
            if num_cb > 2:
                cb_count = self.size / self.BufferSize / (num_cb-2)
            else:
                cb_count = 0
            i = total_bytes = 0
            cb(total_bytes, self.size)
        l = fp.read(self.BufferSize)
        while len(l) > 0:
            http_conn.send(l)
            if cb:
                total_bytes += len(l)
                i += 1
                if i == cb_count:
                    cb(total_bytes, self.size)
                    i = 0
            l = fp.read(self.BufferSize)
        [IF_MASK]
            cb(total_bytes, self.size)
        response = http_conn.getresponse()
        body = response.read()
        fp.seek(0)
        self.bucket.connection.debug = save_debug
        if response.status == 500 or response.status == 503 or                    response.getheader('location'):

            return response
        elif response.status >= 200 and response.status <= 299:
            self.etag = response.getheader('etag')
            if self.etag != '"%s"'  % self.md5:
                raise S3DataError('ETag from S3 did not match computed MD5')
            return response
        else:
            raise S3ResponseError(response.status, response.reason, body)

    if not headers:
        headers = {}
    else:
        headers = headers.copy()
    headers['User-Agent'] = UserAgent
    headers['Content-MD5'] = self.base64md5
    if headers.has_key('Content-Type'):
        self.content_type = headers['Content-Type']
    elif self.path:
        self.content_type = mimetypes.guess_type(self.path)[0]
        if self.content_type == None:
            self.content_type = self.DefaultContentType
        headers['Content-Type'] = self.content_type
    else:
        headers['Content-Type'] = self.content_type
    headers['Content-Length'] = self.size
    headers['Expect'] = '100-Continue'
    headers = boto.utils.merge_meta(headers, self.metadata)
    return self.bucket.connection.make_request('PUT', self.bucket.name,
            self.name, headers, sender=sender)

def set_contents_from_file(self, fp, headers=None, replace=True, cb=None, num_cb=10, policy=None):

    [IF_MASK]
        if headers:
            headers['x-amz-acl'] = policy
        else:
            headers = {'x-amz-acl' : policy}
    if hasattr(fp, 'name'):
        self.path = fp.name
    if self.bucket != None:
        self._compute_md5(fp)
        if self.name == None:
            self.name = self.md5
        if not replace:
            k = self.bucket.lookup(self.name)
            if k:
                return
        self.send_file(fp, headers, cb, num_cb)

def get_file(self, fp, headers=None, cb=None, num_cb=10, torrent=False):

    if cb:
        if num_cb > 2:
            cb_count = self.size / self.BufferSize / (num_cb-2)
        else:
            cb_count = 0
        i = total_bytes = 0
        cb(total_bytes, self.size)
    save_debug = self.bucket.connection.debug
    if self.bucket.connection.debug == 1:
        self.bucket.connection.debug = 0

    if torrent: torrent = "torrent"
    self.open('r', headers, query_args=torrent)
    for bytes in self:
        fp.write(bytes)
        [IF_MASK]
            total_bytes += len(bytes)
            i += 1
            if i == cb_count:
                cb(total_bytes, self.size)
                i = 0
    if cb:
        cb(total_bytes, self.size)
    self.close()
    self.bucket.connection.debug = save_debug

def diff_text(self, pos, old_text, new_text):
    old = self.text_split(old_text)
    new = self.text_split(new_text)
    matcher = SequenceMatcher(None, old, new)

    def wrap(tag, words):
        return self.mark_text(pos, u''.join(words), tag)

    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag == 'replace':
            wrap('del', old[i1:i2])
            wrap('ins', new[j1:j2])
        elif tag == 'delete':
            wrap('del', old[i1:i2])
        [IF_MASK]
            wrap('ins', new[j1:j2])
        else:
            self.append(TEXT, u''.join(old[i1:i2]), pos)

