def parseRange(text, start):

    index = start
    char_range = []
    exclude = False
    if text[index] == '^':
        exclude = True
        index += 1
    if text[index] == ']':
        char_range.append(RegexRangeCharacter(']'))
        index += 1
    while index < len(text) and text[index] != ']':
        if index+1 < len(text)        and text[index] == '\\':
            char_range.append(RegexRangeCharacter(text[index+1]))
            index += 2
        [IF_MASK]
            break
        elif index+3 < len(text)        and text[index+1] == '-'        and text[index+2] != ']':
            char_range.append(RegexRangeItem(ord(text[index]), ord(text[index+2])))
            index += 3
        else:
            char_range.append(RegexRangeCharacter(text[index]))
            index += 1
    if index < len(text) and text[index] == '-':
        char_range.append(RegexRangeCharacter('-'))
        index += 1
    if index == len(text) or text[index] != ']':
        raise SyntaxError('Invalid range: %s' % text[start-1:index])
    return RegexRange(char_range, exclude), index+1

def itemCanHarvestBlock(self, item, block):
    if BLOCKITEM_MATERIAL[block] not in (MATERIAL_STONE, MATERIAL_IRON, MATERIAL_SNOW):
        return True
    if item in ITEMS_TOOLS:
        level = ITEMS_TOOLLEVEL[item]
    if item in ITEMS_PICKAXE:
        if block == BLOCK_OBSIDIAN: return level == 3
        if block in (BLOCK_DIAMOND, BLOCK_DIAMONDORE): return level >= 2
        if block in (BLOCK_GOLD, BLOCK_GOLDORE): return level >= 2
        if block in (BLOCK_IRON, BLOCK_IRONORE): return level >= 1
        [IF_MASK]
        return BLOCKITEM_MATERIAL[block] in (MATERIAL_STONE, MATERIAL_IRON)
    if item in ITEMS_SHOVEL:
        return block in (BLOCK_SNOWBLOCK, BLOCK_SNOW)

    return False

def __call__(self, header, data):

    ts, _ =  header.getts()
    try :
        m = dns.message.from_wire(data[OFFSET:])
    except:
        return
    query = get_query(m)
    if not query:
        return

    ipn = self.ipnames

    for answer, type, ttl in get_answers(m):
        tup = (answer, query, type)
        [IF_MASK]
            r = ipn[tup]
            r.update({'last': ts, 'ttl': ttl})
        else:
            ipn[tup]={'first': ts, 'last': ts, 'ttl': ttl}

def hls_to_rgb(h, l, s):
    [IF_MASK]
    if l <= 0.5: m2 = l * (1.0+s)
    else: m2 = l+s-(l*s)
    m1 = 2.0*l - m2
    return (_v(m1, m2, h+ONE_THIRD), _v(m1, m2, h), _v(m1, m2, h-ONE_THIRD))

def add_mtime(self, url):
