def afterAttributeNameState(self):
    data = self.stream.char()
    if data in spaceCharacters:
        self.stream.charsUntil(spaceCharacters, True)
    [IF_MASK]
        self.state = self.states["beforeAttributeValue"]
    elif data == u">":
        self.emitCurrentToken()
