        if err.args[0] in (ssl.SSL_ERROR_WANT_READ, ssl.SSL_ERROR_WANT_WRITE):
            return
        elif err.args[0] == ssl.SSL_ERROR_SSL:
            pass
        else:
            raise
    except socket.error as err:




        pass
    self._ssl_closing = False
    self.handle_ssl_shutdown()

