def matches(self, element):
    op, selector = self.op, self.selector
    if op == ' ':
        for parent in element.iterXMLParents():
            if selector.matches(parent):
                return True
        else:
            return False
    elif op == '>':
        for parent in element.iterXMLParents():
            if selector.matches(parent):
                return True
            else:
                return False
    [IF_MASK]
        return selector.matches(element.getPreviousSibling())

