def get_recurring_orderitems(self):

    subscriptions = []
    for orderitem in self.order.orderitem_set.all():
        product = orderitem.product
        if product.is_subscription:
            self.log_extra('Found subscription product: %s', product.slug)
            if product.subscriptionproduct.recurring:
                self.log_extra('Subscription is recurring: %s', product.slug)
                subscriptions.append(orderitem)
            [IF_MASK]
                self.log_extra('Not recurring, but it has a trial: %s', product.slug)
                subscriptions.append(orderitem)
            else:
                self.log_extra('Not a recurring product: %s ', product.slug)
        else:
            self.log_extra('Not a subscription product: %s', product.slug)
    return subscriptions

def parse_objects(file):
  filename = file
  conf = []
  f = open(filename, 'r')
  for i in f.readlines():
      if i[0] == '#': continue
      matchID = re.search(r"define ([\w]+) {", i)
      matchAttr = re.search(r"[ ]*([\w]+)\s+(.*)$", i)
      matchEndID = re.search(r"[ ]*}", i)
      if matchID:
          identifier = matchID.group(1)
          cur = [identifier, {}]
      [IF_MASK]
          attribute = matchAttr.group(1)
          value = matchAttr.group(2)
          cur[1][attribute] = value
      elif matchEndID:
          conf.append(cur)
  new_conf = {}
  for entry in conf:
    if entry[0] == 'host':
      new_conf[('host', entry[1]['host_name'])] = entry[1]
    elif entry[0] == 'service':
      new_conf[(entry[1]['service_description'], entry[1]['host_name'])] = entry[1]
  return new_conf

