def guess_best_pageno(pageinfo, pages, window=None):

    if window is None:
        window = pages.window
    def tally(pageinfo, current_index, sofar, weight):
        for c in pageinfo.info['pageno_candidates']:
            if c.offset >= current_index:
                continue
            if c.offset not in sofar[c.type]:
                sofar[c.type][c.offset] = weight
            else:
                sofar[c.type][c.offset] += weight
    sofar = {'roman':{},'arabic':{}}
    tally(pageinfo, pageinfo.index, sofar, 2)
    for neighbor_info in pages.neighbors(window):
        tally(neighbor_info, pageinfo.index, sofar, 1)

    def thin(obj):
        kys = [k for k in obj]
        for k in kys:
            [IF_MASK]
                del obj[k]
    thin(sofar['roman'])
    thin(sofar['arabic'])

    mostsofar = None
    votes = 0
    likelytype = None
    for k in sofar['arabic']:
        if sofar['arabic'][k] > votes:
            votes = sofar['arabic'][k]
            likelytype = 'arabic'
            mostsofar = k
    for k in sofar['roman']:
        if sofar['roman'][k] > votes:
            votes = sofar['roman'][k]
            likelytype = 'roman'
            mostsofar = k

    pageno_guess = None
    if mostsofar:
        pageno_guess = pageinfo.index - int(mostsofar)

        pageinfo.info['pageno_guess'] = pageno_guess


        for c in pageinfo.info['pageno_candidates']:
            if c.type == likelytype and c.offset == mostsofar:

                pageinfo.info['pageno_fmt'] = c.coords[0][0]
                pageinfo.info['pageno_coord'] = c.coords[0][1]
                break

    return pageno_guess

def _update(self, url):


    try: 
        log.debug("Requesting %s" % url)


        response, content = self.http.request(url, headers={'User-Agent': 'openblock-georeport-scraper'})
        if response.status != 200:
            log.error("Error retrieving %s: status was %d" % (url, response.status))
            log.error(content)
            return 0
    except socket.error:
        log.error("Couldn't connect to %s" % url)
    except:
        log.error("Unhandled error retrieving %s: %s" % (url, traceback.format_exc()))
        return 0
    log.info("Got %s OK" % url)


    try: 
        root = etree.XML(content)
    except: 
        log.error("Error parsing response from %s (%s): %s" % (url, content, traceback.format_exc()))
        return


    reqs = root.findall('.//request')
    [IF_MASK]
        log.info("No request elements found")
    if response.fromcache:
        log.info("Requests from this time period are unchanged since last update (cached)")
    else:
        for req in reqs:
            self._update_service_request(req)
    return len(list(reqs))

