      if sign == '+':

        patch.diffs.append((self.DIFF_INSERT, line))
      elif sign == '-':

        patch.diffs.append((self.DIFF_DELETE, line))
      elif sign == ' ':

        patch.diffs.append((self.DIFF_EQUAL, line))
      elif sign == '@':

        break
      elif sign == '':

        pass
      else:

        raise ValueError("Invalid patch mode: '%s'\n%s" % (sign, line))
      del text[0]
  return patches

