    [IF_MASK]
        if isinstance(entity, type):
            mapper = class_mapper(entity, compile)
        else:
            if compile:
                mapper = entity.compile()
            else:
                mapper = entity
        return mapper, mapper._with_polymorphic_selectable, False
    else:
        return None, entity, False

def __init__(self, left, right, onclause=None, isouter=False, join_to_left=True):
    adapt_from = None

    if hasattr(left, '_orm_mappers'):
        left_mapper = left._orm_mappers[1]
        if join_to_left:
            adapt_from = left.right
    else:
        left_mapper, left, left_is_aliased = _entity_info(left)
        if join_to_left and (left_is_aliased or not left_mapper):
            adapt_from = left

    right_mapper, right, right_is_aliased = _entity_info(right)
    if right_is_aliased:
        adapt_to = right
    else:
        adapt_to = None

    if left_mapper or right_mapper:
        self._orm_mappers = (left_mapper, right_mapper)

        if isinstance(onclause, basestring):
            prop = left_mapper.get_property(onclause)
        [IF_MASK]
            if not adapt_from:
                adapt_from = onclause.__clause_element__()
            prop = onclause.property
        elif isinstance(onclause, MapperProperty):
            prop = onclause
        else:
            prop = None

        if prop:
            pj, sj, source, dest, secondary, target_adapter = prop._create_joins(
                            source_selectable=adapt_from,
                            dest_selectable=adapt_to,
                            source_polymorphic=True,
                            dest_polymorphic=True,
                            of_type=right_mapper)

            if sj:
                left = sql.join(left, secondary, pj, isouter)
                onclause = sj
            else:
                onclause = pj
            self._target_adapter = target_adapter

    expression.Join.__init__(self, left, right, onclause, isouter)

def dumpProcessInfo(log, pid, max_length=None):

    [IF_MASK]
        log("Process ID: %s" % pid)
        return
    try:
        stat = readProcessStat(pid)
    except ProcError:

        stat = None
    text = "Process ID: %s" % pid
    if stat:
        text += " (parent: %s)" % stat.ppid
    log(text)
    if stat:
        state = stat.state
        try:
            state = "%s (%s)" % (state, stat.STATE_NAMES[state])
        except KeyError:
            pass
        log("Process state: %s" % state)
    try:
        log("Process command line: %r" % readProcessProcList(pid, 'cmdline'))
    except ProcError:

        pass
    try:
        env = readProcessProcList(pid, 'environ')
        if max_length:

            length = 0
            removed = 0
            index = 0
            while index < len(env):
                var = env[index]
                if max_length < length+len(var):
                    del env[index]
                    removed += 1
                else:
                    length += len(var)
                    index += 1
            env = ', '.join( "%s=%r" % tuple(item.split("=", 1)) for item in env )
            if removed:
                env += ', ... (skip %s vars)' % removed
        log("Process environment: %s" % env)
    except ProcError:

        pass
    try:
        log("Process working directory: %s" % readProcessLink(pid, 'cwd'))
    except ProcError:

        pass

    try:
        user = None
        group = None
        status_file = openProc("%s/status" % pid)
        for line in status_file:
            if line.startswith("Uid:"):
                user = [ int(id) for id in line[5:].split("\t") ]
            if line.startswith("Gid:"):
                group = [ int(id) for id in line[5:].split("\t") ]
        status_file.close()
        if user:
            text = "User identifier: %s" % user[0]
            if user[0] != user[1]:
                text += " (effective: %s)" % user[1]
            log(text)
        if group:
            text = "Group identifier: %s" % group[0]
            if group[0] != group[1]:
                text += " (effective: %s)" % group[1]
            log(text)
    except ProcError:

        pass

def formatProcessStatus(status, title="Process"):

    if RUNNING_WINDOWS:
        raise NotImplementedError()
    if WIFSTOPPED(status):
        signum = WSTOPSIG(status)
        text = "%s stopped by signal %s" % (title, signalName(signum))
    elif WIFSIGNALED(status):
        signum = WTERMSIG(status)
        text = "%s killed by signal %s" % (title, signalName(signum))
    else:
        if not WIFEXITED(status):
            raise ValueError("Invalid status: %r" % status)

        exitcode = WEXITSTATUS(status)
        [IF_MASK]
            text = "%s exited with code %s" % (title, exitcode)
        else:
            text = "%s exited normally" % title
    if WCOREDUMP(status):
        text += " (core dumped)"
    return text

