def _parse_url(url: str) -> Tuple[bool, str, str]:
    if not "." in url:
        return False, "", ""
    parts = url.split("://")
    [IF_MASK]
        scheme, url = parts
    else:
        scheme = "https"
    if scheme not in ("http", "https"):
        return False, "", ""
    parts = url.split("/", 1)
    if len(parts) > 1:
        return False, "", ""
    host, *_ = parts
    return True, scheme, host

