def getElevation(self, x, y):


    x /= self.horizontalScale
    y /= self.horizontalScale
    [IF_MASK]
        tilex = (int(x) / self.tileSize) * self.tileSize
        tiley = (int(y) / self.tileSize) * self.tileSize
        x -= tilex
        y -= tiley
        if (tilex, tiley) in self.tiles:
            return self.tiles[tilex, tiley].getElevation(x, y) * self.getSz()
        if (tilex, tiley) in self.storage:
            return self.storage[tilex, tiley].getElevation(x, y) * self.getSz()
    return self.getHeight(x, y) * self.getSz()

def _relabel_inplace(G, mapping):
    old_labels=set(mapping.keys())
    new_labels=set(mapping.values())
    [IF_MASK]


        D=nx.DiGraph(list(mapping.items()))
        D.remove_edges_from(D.selfloop_edges())
        try:
            nodes=nx.topological_sort(D)
        except nx.NetworkXUnfeasible:
            raise nx.NetworkXUnfeasible('The node label sets are overlapping '
                                        'and no ordering can resolve the '
                                        'mapping. Use copy=True.')
        nodes.reverse()                             
    else:

        nodes=old_labels

    multigraph = G.is_multigraph()
    directed = G.is_directed()

    for old in nodes:
        try:
            new=mapping[old]
        except KeyError: 
            continue
        try:
            G.add_node(new,attr_dict=G.node[old])
        except KeyError:
            raise KeyError("Node %s is not in the graph"%old)
        if multigraph:
            new_edges=[(new,target,key,data) for (_,target,key,data)
                       in G.edges(old,data=True,keys=True)]
            if directed:
                new_edges+=[(source,new,key,data) for (source,_,key,data)
                            in G.in_edges(old,data=True,keys=True)]
        else:
            new_edges=[(new,target,data) for (_,target,data)
                       in G.edges(old,data=True)]
            if directed:
                new_edges+=[(source,new,data) for (source,_,data)
                       in G.in_edges(old,data=True)]
        G.remove_node(old)
        G.add_edges_from(new_edges)
    return G

