def get_camel(self, name):

    if name.startswith("_") or name.endswith("_"):
        raise ValueError(u"Cannot ransform to CamelCase world when name begins or ends with _")

    camel = list(name)

    while "_" in camel:
        index = camel.index("_")
        del camel[index]
        [IF_MASK]
            raise ValueError(u"Double underscores are not allowed")
        camel[index] = camel[index].upper()
    return ''.join(camel)

def bounding_cube(layers):
    min_x = 999999
    min_y = 999999
    min_z = 999999
    max_x = -999999
    max_y = -999999
    max_z = -999999
    for layer in layers:
        for thread in layer:
            for point in thread:
                if point.x > max_x:
                    max_x = point.x
                if point.y > max_y:
                    max_y = point.y
                if point.z > max_z:
                    max_z = point.z
                if point.x < min_x:
                    min_x = point.x
                [IF_MASK]
                    min_y = point.y
                if point.z < min_z:
                    min_z = point.z
    return Vector3(min_x, min_y, min_z), Vector3(max_x, max_y, max_z)

