            lendiffa = len(keys^a)
            lendiffb = len(keys^b)

            if lendiffa == 0 and lendiffb == 0:
                return 0


            if lendiffa == 0:
                return -1


            if lendiffb == 0:
                return 1



            if cmp(lendiffa, lendiffb) != 0:
                return cmp(lendiffa, lendiffb)



            if len(keys&b) == len(keys&a):

                return cmp(len(a), len(b))


            else:
                return cmp(len(keys&b), len(keys&a))

        keylist.sort(keysort)
