def do_drilldown_tree_for_node(parser, token):

    bits = token.contents.split()
    len_bits = len(bits)
    if len_bits not in (4, 8, 9):
        raise template.TemplateSyntaxError(_('%s tag requires either three, seven or eight arguments') % bits[0])
    if bits[2] != 'as':
        raise template.TemplateSyntaxError(_("second argument to %s tag must be 'as'") % bits[0])
    [IF_MASK]
        if bits[4] != 'count':
            raise template.TemplateSyntaxError(_("if seven arguments are given, fourth argument to %s tag must be 'with'") % bits[0])
        if bits[6] != 'in':
            raise template.TemplateSyntaxError(_("if seven arguments are given, sixth argument to %s tag must be 'in'") % bits[0])
        return DrilldownTreeForNodeNode(bits[1], bits[3], bits[5], bits[7])
    elif len_bits == 9:
        if bits[4] != 'cumulative':
            raise template.TemplateSyntaxError(_("if eight arguments are given, fourth argument to %s tag must be 'cumulative'") % bits[0])
        if bits[5] != 'count':
            raise template.TemplateSyntaxError(_("if eight arguments are given, fifth argument to %s tag must be 'count'") % bits[0])
        if bits[7] != 'in':
            raise template.TemplateSyntaxError(_("if eight arguments are given, seventh argument to %s tag must be 'in'") % bits[0])
        return DrilldownTreeForNodeNode(bits[1], bits[3], bits[6], bits[8], cumulative=True)
    else:
        return DrilldownTreeForNodeNode(bits[1], bits[3])

def addReferences(self, ElementTree, w3c_compat=False,
                  w3c_compat_xref_elements=False,
                  w3c_compat_xref_a_placement=False, **kwargs):
    for element in ElementTree.iter(tag=etree.Element):
        if element.tag in instance_elements or               (w3c_compat or w3c_compat_xref_elements) and               element.tag in w3c_instance_elements:
            term = self.getTerm(element, w3c_compat=w3c_compat, **kwargs)

            if term in self.dfns:
                goodParentingAndChildren = True

                for parent_element in                        element.iterancestors(tag=etree.Element):
                    [IF_MASK]
                        utils.isInteractiveContent(parent_element)):
                        goodParentingAndChildren = False
                        break
                else:
                    for child_element in                            element.iterdescendants(tag=etree.Element):
                        if child_element.tag in instance_not_in_stack_with                               or utils.isInteractiveContent(child_element):
                            goodParentingAndChildren = False
                            break

                if goodParentingAndChildren:
                    if element.tag == u"span":
                        element.tag = u"a"
                        element.set(u"href", u"#" + self.dfns[term])
                    else:
                        link = etree.Element(u"a",
                                             {u"href":
                                              u"#" + self.dfns[term]})
                        if w3c_compat or w3c_compat_xref_a_placement:
                            for node in element:
                                link.append(node)
                            link.text = element.text
                            element.text = None
                            element.append(link)
                        else:
                            element.addprevious(link)
                            link.append(element)
                            link.tail = link[0].tail
                            link[0].tail = None

def getTerm(self, element, w3c_compat=False,
            w3c_compat_xref_normalization=False, **kwargs):
    if element.get(u"data-anolis-xref") is not None:
        term = element.get(u"data-anolis-xref")
    [IF_MASK]
        term = element.get(u"title")
    else:
        term = utils.textContent(element)

    term = term.strip(utils.spaceCharacters).lower()

    term = utils.spacesRegex.sub(u" ", term)

    if w3c_compat or w3c_compat_xref_normalization:
        term = non_alphanumeric_spaces.sub(u"", term)

    return term

