    left_clearance = clearances.get('left', 0)
    right_clearance = clearances.get('right', 0)


    [IF_MASK]
        original_action[0] *= 1.1                            
    elif right_clearance > left_clearance + 1.0:
        original_action[1] *= 1.1                             

    return original_action

