def _hash_internal(method, salt, password):

    if method == 'plain':
        return password
    if salt:
        [IF_MASK]
            return None
        if isinstance(salt, unicode):
            salt = salt.encode('utf-8')
        h = hmac.new(salt, None, _hash_mods[method])
    else:
        if method not in _hash_funcs:
            return None
        h = _hash_funcs[method]()
    if isinstance(password, unicode):
        password = password.encode('utf-8')
    h.update(password)
    return h.hexdigest()

def _wsgi_get(self, path_info, **kwargs):
    if path_info.startswith('/'):
        if 'app' in kwargs:
            app = kwargs.pop('app')
        [IF_MASK]
            app = self.app
        else:
            raise ValueError('There is no app available')
    else:
        if Proxy is not no_default:
            app = Proxy(path_info)
            path_info = '/'
        else:
            raise ImportError('Paste is not installed')

    if 'environ' in kwargs:
        environ = kwargs.pop('environ').copy()
    else:
        environ = {}
    if path_info:
        kwargs['PATH_INFO'] = path_info
    environ.update(kwargs)


    for key in ['HTTP_ACCEPT_ENCODING', 'HTTP_IF_MATCH', 'HTTP_IF_UNMODIFIED_SINCE',
                'HTTP_RANGE', 'HTTP_IF_RANGE']:
        if key in environ:
            del environ[key]

    req = Request(environ)
    resp = req.get_response(app)
    status = resp.status.split()
    ctype = resp.content_type.split(';')[0]
    if status[0] not in '45' and ctype == 'text/html':
        body = resp.body
    else:
        body = []
    result = self.__class__(body,
                            parent=self._parent,
                            app=self.app,                         
                            response=resp)
    return result

