        elif ratio <= self.LUX_K4T:
            b = self.LUX_B4T
            m = self.LUX_M4T
        elif ratio <= self.LUX_K5T:
            b = self.LUX_B5T
            m = self.LUX_M5T
        elif ratio <= self.LUX_K6T:
            b = self.LUX_B6T
            m = self.LUX_M6T
        elif ratio <= self.LUX_K7T:
            b = self.LUX_B7T
            m = self.LUX_M7T
        elif ratio <= self.LUX_K8T:
            b = self.LUX_B8T
            m = self.LUX_M8T
    else:    

        if (ratio >= 0) and (ratio <= self.LUX_K1C):  
            b = self.LUX_B1C
            m = self.LUX_M1C
        elif ratio <= self.LUX_K2C:
            b = self.LUX_B2C
            m = self.LUX_M2C
        elif ratio <= self.LUX_K3C:
            b = self.LUX_B3C
            m = self.LUX_M3C
        elif ratio <= self.LUX_K4C:
            b = self.LUX_B4C
            m = self.LUX_M4C
        elif ratio <= self.LUX_K5C:
            b = self.LUX_B5C
            m = self.LUX_M5C
        elif ratio <= self.LUX_K6C:
            b = self.LUX_B6C
            m = self.LUX_M6C
        elif ratio <= self.LUX_K7C:
            b = self.LUX_B7C
            m = self.LUX_M7C
        elif ratio <= self.LUX_K8C:
            b = self.LUX_B8C
            m = self.LUX_M8C

    temp = ((channel0 * b) - (channel1 * m))

    if temp < 0:
