def __call__(self, env, start_response):
    req = Request(env)

    [IF_MASK]
        try:
            req.headers['Date'] = req.GET['Expires']
            req.headers['Authorization'] =                    'AWS %(AWSAccessKeyId)s:%(Signature)s' % req.GET
        except KeyError:
            return get_err_response('InvalidArgument')(env, start_response)

    if not 'Authorization' in req.headers:
        return self.app(env, start_response)

    try:
        account, signature =                req.headers['Authorization'].split(' ')[-1].rsplit(':', 1)
    except Exception:
        return get_err_response('InvalidArgument')(env, start_response)

    try:
        controller, path_parts = self.get_controller(req.path)
    except ValueError:
        return get_err_response('InvalidURI')(env, start_response)

    token = base64.urlsafe_b64encode(canonical_string(req))

    controller = controller(env, self.app, account, token, **path_parts)

    if hasattr(controller, req.method):
        res = getattr(controller, req.method)(env, start_response)
    else:
        return get_err_response('InvalidURI')(env, start_response)

    return res(env, start_response)

