def searchwiki(txt, lang='en'):
    input = []     
    for i in txt.split():
        [IF_MASK]
            if len(i) != 3:
                continue
            else:
                lang = i[1:]
            continue
        input.append(i.strip().capitalize())
    what = "_".join(input)
    url = u'http://%s.wikipedia.org/wiki/Special:Export/%s' % (lang,quote(what.encode('utf-8')))
    url2 = u'http://%s.wikipedia.org/wiki/%s' % (lang,quote(what.encode('utf-8')))
    txt = getwikidata(url)
    if not txt:
        return ("", url2)
    if 'from other capitalisation' in txt:
        what = what.title()
        url = u'http://%s.wikipedia.org/wiki/Special:Export/%s' % (lang,quote(what.encode('utf-8')))
        url2 = u'http://%s.wikipedia.org/wiki/%s' % (lang,quote(what.encode('utf-8')))
        txt = getwikidata(url)
    if '#REDIRECT' in txt or '#redirect' in txt:
        redir = ' '.join(txt.split()[1:])
        url = u'http://%s.wikipedia.org/wiki/Special:Export/%s' % (lang,quote(redir.encode('utf-8')))
        url2 = u'http://%s.wikipedia.org/wiki/%s' % (lang,quote(redir.encode('utf-8')))
        txt = getwikidata(url)
    return (txt, url2)

def handle_noargs(self,**options):
    opts=None
    args=None

    log.info('starting to update sources')
    sources = settings.AGRO_SETTINGS['source_list']

    if args and len(args) > 1:
        sources = args[1:]
        for source in sources:
            [IF_MASK]
                log.warning('%s is not a valid source, removing from update list.', source)
                sources.remove(source)

    args = {}
    force_run = False
    if hasattr(opts, 'force'):
        if opts.force == True:
            force_run = True

    for s in import_source_modules(source_list=sources, class_name='retrieve'):
        log.info('')
        log.info('trying to update %s', s.__name__)

        base_name = s.__name__[s.__name__.rfind('.')+1:]

        if base_name in settings.AGRO_SETTINGS['api_keys'].keys():
            args['api_key'] = settings.AGRO_SETTINGS['api_keys'][base_name]

        if base_name in settings.AGRO_SETTINGS['accounts'].keys():
            account = settings.AGRO_SETTINGS['accounts'][base_name]
        else:
            log.error('no credentials for %s', base_name)
            continue

        if isinstance(account, (tuple, list)):
            for a in account:
                args['account'] = a
                log.info('using %s account: %s', base_name, args['account'])
                s.retrieve(force_run, **args)
        else:
            args['account'] = account
            log.info('using %s account: %s', base_name, args['account'])
            s.retrieve(force_run, **args)

        log.info('done updating %s', s.__name__)
        log.info('')

def __getitem__(self, index):

    self.__check_okay_to_chain()
    if isinstance(index, types.SliceType):
        if index.step is not None:
            raise IndexError("Cursor instances do not support slice steps")

        skip = 0
        if index.start is not None:
            if index.start < 0:
                raise IndexError("Cursor instances do not support negative indices")
            skip = index.start

        if index.stop is not None:
            limit = index.stop - skip
            if limit <= 0:
                raise IndexError("stop index must be greater than start index for slice %r" % index)
        else:
            limit = 0

        self.__skip = skip
        self.__limit = limit
        return self

    [IF_MASK]
        if index < 0:
            raise IndexError("Cursor instances do not support negative indices")
        clone = self.clone()
        clone.skip(index + self.__skip)
        clone.limit(-1)                   
        for doc in clone:
            return doc
        raise IndexError("no such item for Cursor instance")
    raise TypeError("index %r cannot be applied to Cursor instances" % index)

