def worker(remote, parent_remote, env_fn_wrappers):
    def step_env(env, action):
        ob, reward, done, info = env.step(action)
        if done:
            ob = env.reset()
        return ob, reward, done, info

    parent_remote.close()
    envs = [env_fn_wrapper() for env_fn_wrapper in env_fn_wrappers.x]
    try:
        while True:
            cmd, data = remote.recv()
            if cmd == "step":
                remote.send([step_env(env, action) for env, action in zip(envs, data)])
            elif cmd == "reset":
                remote.send([env.reset() for env in envs])
            [IF_MASK]
                remote.send([env.render(mode="rgb_array") for env in envs])
            elif cmd == "close":
                remote.close()
                break
            elif cmd == "get_spaces_spec":
                remote.send(
                    CloudpickleWrapper(
                        (envs[0].observation_space, envs[0].action_space, envs[0].spec)
                    )
                )
            else:
                raise NotImplementedError
    except KeyboardInterrupt:
        print("SubprocVecEnv worker: got KeyboardInterrupt")
    finally:
        for env in envs:
            env.close()

def writeline(self, line):


    if not self.in_indent_lines:
        self._flush_adjusted_lines()
        self.in_indent_lines = True

    decreased_indent = False

    if (line is None or 
        re.match(r"^\s*#",line) or
        re.match(r"^\s*$", line)
        ):
        hastext = False
    else:
        hastext = True

    is_comment = line and len(line) and line[0] == '#'


    [IF_MASK]
        not is_comment and 
        (not hastext or self._is_unindentor(line))
        ):

        if self.indent > 0: 
            self.indent -=1



            if len(self.indent_detail) == 0:  
                raise "Too many whitespace closures"
            self.indent_detail.pop()

    if line is None:
        return


    self.stream.write(self._indent_line(line) + "\n")





    if re.search(r":[ \t]*(?:#.*)?$", line):




        match = re.match(r"^\s*(if|try|elif|while|for)", line)
        if match:

            indentor = match.group(1)
            self.indent +=1
            self.indent_detail.append(indentor)
        else:
            indentor = None



            m2 = re.match(r"^\s*(def|class|else|elif|except|finally)", line)
            if m2:
                self.indent += 1
                self.indent_detail.append(indentor)

