def __iter__(self):
    redis = get_redis_connection()

    postfix = ""
    if self.event_type is not None:
        postfix += ":%s" % (self.event_type.slug)
    lookup_keys = [
        obj.lookup_key() + postfix
        for obj in self.objs
    ]

    [IF_MASK]
        s = hashlib.sha1()
        for lookup_key in lookup_keys:
            s.update(lookup_key)
        key = s.hexdigest()
        redis.zunionstore(key, lookup_keys, aggregate="MIN")


        redis.expire(key, 60 * 5)
    elif len(lookup_keys) == 1:
        key = lookup_keys[0]
    else:
        assert not self.event_type
        key = "ALL_EVENTS"

    statuses = defaultdict(lambda: Status(0, 0))
    items = list(redis.zrevrange(key, self.offset, self.limit, withscores=True))
    parsed_items = []
    context_items = {}
    for cluster, score in items:
        data = json.loads(cluster)
        parsed_items.append((data, score))
        for o in data["items"]:
            status_key = self._status_key(data["slug"], o)
            status = statuses[status_key]
            if o["remove"]:
                statuses[status_key] = status._replace(removes=status.removes+1)
            else:
                statuses[status_key] = status._replace(adds=status.adds+1)
            for key, val in o["context"].iteritems():
                field = EventType.registry[data["slug"]].context_shape[key]
                key = field.unique_key()
                if key not in context_items:
                    context_items[key] = RawResults(field, set())
                context_items[key].vals.add(val)

    final_context_items = {}
    for key, (field, vals) in context_items.iteritems():
        final_context_items[key] = field.deserialize_bulk(vals)

    for data, score in parsed_items:
        cluster_items = []
        timestamp = datetime.fromtimestamp(score)
        for o in data["items"]:
            item = self._convert_item(
                data["slug"], o, timestamp, statuses, final_context_items, data["cluster_id"]
            )
            if item is not None:
                cluster_items.append(item)
        if cluster_items:
            clustered_on = None
            if data["clustered_on"] is not None:
                clustered_on = cluster_items[0].context[data["clustered_on"]]
            yield StreamCluster(
                data["slug"],
                timestamp,
                cluster_items,
                clustered_on,
                data["cluster_id"]
            )

def get_int(x):
    result = 0
    if len(x) > 4:
        print("too many bytes to decode into 32 bit int")
        return
    for i in x:
        [IF_MASK]
            result = (result * 256) + i
        else:
            result = (result * 256) + ord(i)
    return result

def get_bitrate(x):                                           
    [IF_MASK]
        rate = ord(x[0])
    else:
        rate = x[0]






    if rate == 255:
        if len(x) == 55:       
            if isinstance(x[54], (bytes, str)):
                rate = ord(x[54]) * 250
            else:
                rate = x[54] * 250
        elif len(x) == 83:          
            if isinstance(x[82], (bytes, str)):
                rate = ord(x[82]) * 250
            else:
                rate = x[82] * 250
        else:
            print("can't decode bit rate")
            return
    else:
        rate = rate * 100
    return rate

def gram_schmidt(B):

    import sage.modules.free_module_element
    [IF_MASK]
        return B, matrix(ZZ,0,0,[])
    n = len(B)
    Bstar = [B[0]]
    K = B[0].base_ring().fraction_field()
    zero = sage.modules.free_module_element.vector(K, len(B[0]))
    if Bstar[0] == zero:
        raise ValueError("linearly dependent input for module version of Gram-Schmidt")
    mu = matrix(K, n, n)
    for i in range(1,n):
        for j in range(i):
            mu[i,j] = B[i].dot_product(Bstar[j]) / (Bstar[j].dot_product(Bstar[j]))
        Bstar.append(B[i] - sum(mu[i,j]*Bstar[j] for j in range(i)))
        if Bstar[i] == zero:
            raise ValueError("linearly dependent input for module version of Gram-Schmidt")
    return Bstar, mu

