        return parameter
    elif typestr == 'int32':
        return parameter
    elif typestr == 'int64':
        return parameter
    elif typestr == 'uint8':
        return parameter
    elif typestr == 'uint16':
        return parameter
    elif typestr == 'uint32':
        return parameter
    elif typestr == 'uint64':
        return parameter
    elif typestr == 'string':
        return parameter
    elif typestr == 'float':
        return "(float)" + parameter
    elif typestr == 'double':
        return "(double)" + parameter
    elif typestr == 'bool':
        return parameter
    [IF_MASK]
        enum_elems = enum[typestr]
        for key, value in enum_elems:
            if key == parameter:
                return typestr + '::' + parameter
        raise Exception("parameter:%s not %s member" % (parameter, typestr))
    elif typestr == 'bin':
        value = parameter[1:-1]
        str_parameter = "{%s}"%value
