            tds = tr('td')
            if len(tds) == 2:
                if (tds[0].get('colspan') == '2' and
                        tds[1].get('class') == 'subtext'):
                    score = tds[1].span.string
                    if score.endswith(' points'):
                        score = int(score[:-7])
                    user = tds[1].a.string
                    s.update(score=score, user=user)
                    yield s
                    s={}
        s = {}

