            raise EmitterError("invalid character %r in the anchor: %r"
                    % (ch.encode('utf-8'), anchor.encode('utf-8')))
    return anchor

def analyze_scalar(self, scalar):


    if not scalar:
        return ScalarAnalysis(scalar=scalar, empty=True, multiline=False,
                allow_flow_plain=False, allow_block_plain=True,
                allow_single_quoted=True, allow_double_quoted=True,
                allow_block=False)


    block_indicators = False
    flow_indicators = False
    line_breaks = False
    special_characters = False


    inline_spaces = False                                      
    inline_breaks = False                                      
    leading_spaces = False                                   
    leading_breaks = False                                   
    trailing_spaces = False                                  
    trailing_breaks = False                                  
    inline_breaks_spaces = False                                      
    mixed_breaks_spaces = False                   


    [IF_MASK]
        block_indicators = True
        flow_indicators = True


    preceeded_by_space = True


    followed_by_space = (len(scalar) == 1 or
            scalar[1] in u'\0 \t\r\n\x85\u2028\u2029')


    spaces = False


    breaks = False



    mixed = False



    leading = False

    index = 0
    while index < len(scalar):
        ch = scalar[index]



        if index == 0:

            if ch in u'#,[]{}&*!|>\'\"%@`': 
                flow_indicators = True
                block_indicators = True
            if ch in u'?:':
                flow_indicators = True
                if followed_by_space:
                    block_indicators = True
            if ch == u'-' and followed_by_space:
                flow_indicators = True
                block_indicators = True
        else:

            if ch in u',?[]{}':
                flow_indicators = True
            if ch == u':':
                flow_indicators = True
                if followed_by_space:
                    block_indicators = True
            if ch == u'#' and preceeded_by_space:
                flow_indicators = True
                block_indicators = True



        if ch in u'\n\x85\u2028\u2029':
            line_breaks = True
        if not (ch == u'\n' or u'\x20' <= ch <= u'\x7E'):
            if (ch == u'\x85' or u'\xA0' <= ch <= u'\uD7FF'
                    or u'\uE000' <= ch <= u'\uFFFD') and ch != u'\uFEFF':
                unicode_characters = True
                if not self.allow_unicode:
                    special_characters = True
            else:
                special_characters = True




        if ch in u' \n\x85\u2028\u2029':
            if spaces and breaks:
                if ch != u' ':                                          
                    mixed = True
            elif spaces:
                if ch != u' ':                                  
                    breaks = True
                    mixed = True
            elif breaks:
                if ch == u' ':                     
                    spaces = True
            else:
                leading = (index == 0)
                if ch == u' ':              
                    spaces = True
                else:                       
                    breaks = True


        elif spaces or breaks:
            if leading:
                if spaces and breaks:
                    mixed_breaks_spaces = True
                elif spaces:
                    leading_spaces = True
                elif breaks:
                    leading_breaks = True
            else:
                if mixed:
                    mixed_breaks_spaces = True
                elif spaces and breaks:
                    inline_breaks_spaces = True
                elif spaces:
                    inline_spaces = True
                elif breaks:
                    inline_breaks = True
            spaces = breaks = mixed = leading = False


        if (spaces or breaks) and (index == len(scalar)-1):
            if spaces and breaks:
                mixed_breaks_spaces = True
            elif spaces:
                trailing_spaces = True
                if leading:
                    leading_spaces = True
            elif breaks:
                trailing_breaks = True
                if leading:
                    leading_breaks = True
            spaces = breaks = mixed = leading = False


        index += 1
        preceeded_by_space = (ch in u'\0 \t\r\n\x85\u2028\u2029')
        followed_by_space = (index+1 >= len(scalar) or
                scalar[index+1] in u'\0 \t\r\n\x85\u2028\u2029')


    allow_flow_plain = True
    allow_block_plain = True
    allow_single_quoted = True
    allow_double_quoted = True
    allow_block = True



    if leading_spaces or leading_breaks or trailing_spaces:
        allow_flow_plain = allow_block_plain = allow_block = False



    if trailing_breaks:
        allow_flow_plain = allow_block_plain = False



    if inline_breaks_spaces:
        allow_flow_plain = allow_block_plain = allow_single_quoted = False



    if mixed_breaks_spaces or special_characters:
        allow_flow_plain = allow_block_plain =            allow_single_quoted = allow_block = False


    if line_breaks:
        allow_flow_plain = allow_block_plain = False


    if flow_indicators:
        allow_flow_plain = False


    if block_indicators:
        allow_block_plain = False

    return ScalarAnalysis(scalar=scalar,
            empty=False, multiline=line_breaks,
            allow_flow_plain=allow_flow_plain,
            allow_block_plain=allow_block_plain,
            allow_single_quoted=allow_single_quoted,
            allow_double_quoted=allow_double_quoted,
            allow_block=allow_block)

