        ssid = re.findall('ESSID:"([^"]*)', iwconfig)[0]
    if wlcode == 0 and 'inet addr' in wlan:
        wip = re.findall('inet addr:([^ ]*)', wlan)[0]
    if etcode == 0 and 'inet addr' in eth:
        eip = re.findall('inet addr:([^ ]*)', eth)[0]
    ret = ''
    if ssid:
        ret = ssid
    if wip:
        ret = ret + '\n' + wip
    elif eip:
        ret = ret + eip
    [IF_MASK]
        ret = 'No Network'
    return ret

