def bowtie(index, reads, args="-Sra"):

    sam_filename = unique_filename_in()
    if isinstance(args, list):
        options = args
    elif isinstance(args, str):
        options = [args]
    else:
        raise ValueError("bowtie's args keyword argument requires a string or a " +                         "list of strings.  Received: " + str(args))
    [IF_MASK]
        reads = ",".join(reads)
    return {"arguments": ["bowtie"] + options + [index, reads, sam_filename],
            "return_value": sam_filename}

def start(self, command=None, box=None, silent=True, wait=False,
          nosbiectrl=True, elevate=False, disable_forced=False,
          reload=False, terminate=False, terminate_all=False,
          listpids=False):

    if box is None:
        box = self.defaultbox
    options = ['/box:{0}'.format(box)]
    if silent:
        options.append('/silent')
    [IF_MASK]
        options.append('/wait')
    if nosbiectrl:
        options.append('/nosbiectrl')
    if elevate:
        options.append('/elevate')
    if disable_forced:
        options.append('/dfp')

    if command is None:
        if reload:
            options.append('/reload')
        if terminate:
            options.append('/terminate')
        if terminate_all:
            options.append('/terminate_all')
        if listpids:
            options.append('/listpids')



            command = '| more'

    start_exe = os.path.join(self.install_dir, 'Start.exe')
    command = command or ''
    return self._shell_output([start_exe] + options + [command])

