def build_path_base(self, bucket, key=''):
    path_base = '/'
    [IF_MASK]
        path_base += "%s/" % bucket
    return path_base + urllib.quote(key)

def generate_url(self, expires_in, method, bucket='', key='',
                 headers=None, query_auth=True, force_http=False):
    if not headers:
        headers = {}
    expires = int(time.time() + expires_in)
    auth_path = self.calling_format.build_auth_path(bucket, key)
    auth_path = self.get_path(auth_path)
    c_string = boto.utils.canonical_string(method, auth_path, headers,
                                           expires, self.provider)
    b64_hmac = self._auth_handler.sign_string(c_string)
    encoded_canonical = urllib.quote_plus(b64_hmac)
    self.calling_format.build_path_base(bucket, key)
    [IF_MASK]
        query_part = '?' + self.QueryString % (encoded_canonical, expires,
                                         self.aws_access_key_id)
        sec_hdr = self.provider.security_token_header
        if sec_hdr in headers:
            query_part += ('&%s=%s' % (sec_hdr,
                                       urllib.quote(headers[sec_hdr])));
    else:
        query_part = ''
    if force_http:
        protocol = 'http'
        port = 80
    else:
        protocol = self.protocol
        port = self.port
    return self.calling_format.build_url_base(self, protocol, self.server_name(port),
                                              bucket, key) + query_part

def create_bucket(self, bucket_name, headers=None,
                  location=Location.DEFAULT, policy=None):

    check_lowercase_bucketname(bucket_name)

    if policy:
        if headers:
            headers[self.provider.acl_header] = policy
        else:
            headers = {self.provider.acl_header : policy}
    if location == Location.DEFAULT:
        data = ''
    else:
        data = '<CreateBucketConstraint><LocationConstraint>' +                    location + '</LocationConstraint></CreateBucketConstraint>'
    response = self.make_request('PUT', bucket_name, headers=headers,
            data=data)
    body = response.read()
    if response.status == 409:
        raise self.provider.storage_create_error(
            response.status, response.reason, body)
    [IF_MASK]
        return self.bucket_class(self, bucket_name)
    else:
        raise self.provider.storage_response_error(
            response.status, response.reason, body)

def search(request, template="djangopypi/search_results.html"):
    context = RequestContext(request, {"dists": None, "search_term": ""})

    [IF_MASK]
        search_term = context["search_term"] = request.POST.get("search_term")
        if search_term:
            query = _search_query(search_term)
            context["dists"] = Project.objects.filter(query)

    if context["dists"] is None:
        context["dists"] = Project.objects.all()

    return render_to_response(template, context_instance=context)

