def _innerDrawLabel(self, rowNo, colNo, x, y):


    labelFmt = self.lineLabelFormat
    labelValue = self.data[rowNo][colNo]

    if labelFmt is None:
        labelText = None
    elif type(labelFmt) is str:
        [IF_MASK]
            try:
                labelText = self.lineLabelArray[rowNo][colNo]
            except:
