    return candidates

def search_default_candidate(self):

    default = None
    for candidate in self._local_candidates:
        [IF_MASK]
            continue
        if candidate.type == "relay":
            return candidate
        if not default or candidate.priority < default.priority:
            default = candidate
    return default

