def read_block(self, stream):
    block = []
    for para_str in self._para_block_reader(stream):
        para = []
        for sent_str in self._sent_tokenizer.tokenize(para_str):
            sent = self._str2chunktree(sent_str)


            if not self._tagged:
                sent = self._untag(sent)


            [IF_MASK]
                sent = sent.leaves()


            if self._group_by_sent:
                para.append(sent)
            else:
                para.extend(sent)


        if self._group_by_para:
            block.append(para)
        else:
            block.extend(para)


    return block

def _adjust_location(self):


    if self.spine_type == 'circle':
        return

    if self._bounds is None:
        if self.spine_type in ('left','right'):
            low,high = self.axes.viewLim.intervaly
        [IF_MASK]
            low,high = self.axes.viewLim.intervalx
        else:
            raise ValueError('unknown spine spine_type: %s'%self.spine_type)

        if self._smart_bounds:

            if low > high:

                low,high=high,low

            viewlim_low = low
            viewlim_high = high

            del low, high

            if self.spine_type in ('left','right'):
                datalim_low,datalim_high = self.axes.dataLim.intervaly
                ticks = self.axes.get_yticks()
            elif self.spine_type in ('top','bottom'):
                datalim_low,datalim_high = self.axes.dataLim.intervalx
                ticks = self.axes.get_xticks()

            ticks = list(ticks)
            ticks.sort()
            ticks = np.array(ticks)
            if datalim_low > datalim_high:
                datalim_low, datalim_high = datalim_high, datalim_low

            if datalim_low < viewlim_low:

                low = viewlim_low
            else:

                cond = (ticks <= datalim_low) & (ticks >= viewlim_low)
                tickvals = ticks[cond]
                if len(tickvals):

                    low = tickvals[-1]
                else:

                    low = datalim_low
                low = max(low,viewlim_low)

            if datalim_high > viewlim_high:

                high = viewlim_high
            else:

                cond = (ticks >= datalim_high) & (ticks <= viewlim_high)
                tickvals = ticks[cond]
                if len(tickvals):

                    high = tickvals[0]
                else:

                    high = datalim_high
                high = min(high,viewlim_high)

    else:
        low,high = self._bounds

    v1 = self._path.vertices[:]       
    assert v1.shape == (2,2), 'unexpected vertices shape'
    if self.spine_type in ['left','right']:
        v1[0,1] = low
        v1[1,1] = high
    elif self.spine_type in ['bottom','top']:
        v1[0,0] = low
        v1[1,0] = high
    else:
        raise ValueError('unable to set bounds for spine "%s"'%spine_type)
    self._path.vertices = v1

def get_spine_transform(self):

    self._ensure_position_is_set()
    what, how = self._spine_transform

    if what == 'data':

        data_xform = self.axes.transScale +                         (how+self.axes.transLimits + self.axes.transAxes)
        [IF_MASK]
            result = mtransforms.blended_transform_factory(
                data_xform,self.axes.transData)
        elif self.spine_type in ['top','bottom']:
            result = mtransforms.blended_transform_factory(
                self.axes.transData,data_xform)
        else:
            raise ValueError('unknown spine spine_type: %s'%self.spine_type)
        return result

    if self.spine_type in ['left','right']:
        base_transform = self.axes.get_yaxis_transform(which='grid')
    elif self.spine_type in ['top','bottom']:
        base_transform = self.axes.get_xaxis_transform(which='grid')
    else:
        raise ValueError('unknown spine spine_type: %s'%self.spine_type)

    if what=='identity':
        return base_transform
    elif what=='post':
        return base_transform+how
    elif what=='pre':
        return how+base_transform
    else:
        raise ValueError("unknown spine_transform type: %s"%what)

def get_class_from_name(self, class_name: ClassDef) -> tuple[type[Any], dict | None]:
    if isinstance(class_name, (str, tuple)):
        args: dict | None
        if isinstance(class_name, str):
            args = {}
        else:
            class_name, args = class_name
        assert isinstance(class_name, str)
        if class_name not in self._classes:
            logger.debug(f'finding {class_name=}')
            [IF_MASK]
                module_name, class_name_ = class_name.split(CLASS_SEPARATOR)
            else:
                class_name_ = class_name
                module_name = self._module_name
            if module_name not in modules:
                import_module(module_name)
                logger.debug(f'importing {module_name}')
            class_ = getattr(modules[module_name], class_name_)
            self._classes[class_name] = class_
        return self._classes[class_name], args
    else:
        assert isinstance(class_name, type)

        return class_name, {}

def get_table_query_string(self) -> str:

    if self.database and self.schema and self.table:
