    [IF_MASK]
        return f'"{self.schema}"."{self.table}"'
    elif self.table:
        return f'"{self.table}"'
    else:
        return f"({self.query})"

def get_norm_image_size(self):
    if not self.texture:
        return self.size
    ratio = self.image_ratio
    w, h = self.size
    tw, th = self.texture.size


    [IF_MASK]
        if not self.keep_ratio:
            return w, h
        iw = w
    else:
        iw = min(w, tw)

    ih = iw / ratio


    if ih > h:
        if self.allow_stretch:
            ih = h
        else:
            ih = min(h, th)
        iw = ih * ratio

    return iw, ih

