def endElement(self, name, value, connection):
    if name == 'launchPermission':
        self.name = 'launch_permission'
    elif name == 'productCodes':
        self.name = 'product_codes'
        self.attrs[self.name] = []
    elif name == 'group':
        if self.attrs.has_key('groups'):
            self.attrs['groups'].append(value)
        else:
            self.attrs['groups'] = [value]
    elif name == 'userId':
        [IF_MASK]
            self.attrs['user_ids'].append(value)
        else:
            self.attrs['user_ids'] = [value]
    elif name == 'imageId':
        self.image_id = value
    elif name == 'productCode':
        self.attrs['product_codes'].append(value)
    elif name == 'kernel':
        self.kernel = value
    elif name == 'ramdisk':
        self.ramdisk = value
    else:
        setattr(self, name, value)

def query_by_tcp(q, server, stream=None):
    sock = None
    if stream is None:
        sock = socket.socket()
        sock.connect((server, 53))
        stream = sock.makefile()
    try:
        stream.write(struct.pack('>H', len(q)) + q)
        stream.flush()
        d = stream.read(2)
        if len(d) == 0: raise EOFError()
        reply = stream.read(struct.unpack('>H', d)[0])
        if len(reply) == 0: raise EOFError()
        return reply
    finally:
        [IF_MASK]

