def tearDown(self):
    try:
        sys.path.remove(self.workdir)
    except ValueError:
        pass
    if os.path.exists(self.workdir):
        [IF_MASK]
            for rmfile in os.listdir(self.workdir):
                try:
                    rmfile = os.path.join(self.workdir, rmfile)
                    if os.path.isdir(rmfile):
                        shutil.rmtree(rmfile, ignore_errors=True)
                    else:
                        os.remove(rmfile)
                except IOError:
                    pass
    else:
        os.makedirs(self.workdirs)

def run(self, result=None):
    if result is None:
        result = self.defaultTestResult()
    result.startTest(self)
    try:
        self.setUp()
        self.runTest()
        [IF_MASK]
            sys.path.insert(0, self.projdir)
        doctest_mod_base = self.projname+'_doctest'
        doctest_mod_fqpath = os.path.join(self.directory, doctest_mod_base+'.py')
        shutil.copy(doctest_mod_fqpath, self.projdir)
        doctest.DocTestSuite(self.projname+'_doctest').run(result)    
    except Exception:
        result.addError(self, sys.exc_info())
        result.stopTest(self)
    try:
        self.tearDown()
    except Exception:
        pass

def rpx():
    token = request.form.get('token')

    if not token:
        return redirect('/')

    params = {
        'token': token,
        'apiKey': app.config['JANRAIN_API_KEY'],
        'format': 'json',
    }

    response = urllib2.urlopen('https://rpxnow.com/api/v2/auth_info',
                               urllib.urlencode(params))

    auth_info = json.loads(response.read())

    [IF_MASK]
        return redirect('/')

    profile = auth_info['profile']

    identifier = profile['identifier']

    name = profile.get('displayName') or ''
    email = profile.get('email') or ''
    avatar = profile.get('photo') or ''

    try:
        profile = Profile.objects.get(identifier)
        user = User.objects.get(profile.user)
    except Profile.DoesNotExist:
        user = User.objects.create(
            name=name or identifier,
            email=email,
            avatar=avatar,
        )
        profile = Profile.objects.create(
            pk=identifier,
            user=user.pk,
        )

    if email:
        domain = urlparse.urlparse(email).hostname
        if domain:
            try:
                org = Organization.objects.filter(domain=domain)[0]
            except IndexError:
                pass
            else:
                if not OrganizationMember.objects.exists(org=org.pk, user=user.pk):
                    OrganizationMember.objects.create(
                        org=org.pk,
                        user=user.pk,
                    )

    g.user = user
    session['userid'] = user.pk

    return redirect(session.get('next') or url_for('dashboard'))

def edit_profile():
    def set_api_token(user):
        while True:
            token = uuid.uuid4().hex
            [IF_MASK]
                break
        user.api_token = token

    if not g.user.api_token:
        set_api_token(g.user)

    form = EditProfileForm(name=g.user.name)
    if form.validate_on_submit():
        if form.update_token.data:
            set_api_token(g.user)
        g.user.name = form.name.data

        flash("Your profile was updated successfully!")

        return redirect(url_for('edit_profile'))

    return render_template('auth/edit_profile.html', **{
        'form': form,
    })

