    connection = httplib.HTTPConnection(proxy_uri.host)
    connection.sock = sslobj
    return connection
  elif uri.scheme == 'http':
    proxy_uri = Uri.parse_uri(proxy)
    if not proxy_uri.port:
      proxy_uri.port = '80'
    if proxy_auth:
      headers['Proxy-Authorization'] = proxy_auth.strip()
