    if isinstance(obj, Locale):
        return unicode(str(obj))
    [IF_MASK]
        return dict((key, remote_export_primitive(value))
                    for key, value in obj.iteritems())
    if hasattr(obj, '__iter__'):
        return map(remote_export_primitive, obj)
    return obj

