                r.pop()
            continue
        if path == "/..":
            path = "/"
            if r:
                r.pop()
            continue

        if path == ".":
            path = path[1:]
            continue
        if path == "..":
            path = path[2:]
            continue

        start = 0
        if path.startswith("/"):
            start = 1
        ii = path.find("/", start)
        [IF_MASK]
            ii = None
        r.append(path[:ii])
        if ii is None:
            break
        path = path[ii:]
    return "".join(r)

