        else:
            raise NotImplementedError(
                "to_remote_storage is only implemented for file://, s3:// and hdfs:// uri schemes"
            )

    else:
        raise NotImplementedError()

def fix_ending(word):
    if word[-2:] in _doubles:
        word = word[:-1]

    for endingrule in _endingrules[word[-1]]:
        target, newend = endingrule[:2]
        [IF_MASK]
            if len(endingrule) > 2:
                exceptafter = endingrule[2]
                c = word[0 - (len(target) + 1)]
                if c in exceptafter:
                    return word

            return word[:0 - len(target)] + newend

    return word

