def RandomPoset(n,p):

    try:
        n = Integer(n)
    except:
        raise TypeError("number of elements must be an integer, not {0}".format(n))
    if n < 0:
        raise ValueError("number of elements must be non-negative, not {0}".format(n))
    try:
        p = float(p)
    except:
        raise TypeError("probability must be a real number, not {0}".format(p))
    if p < 0 or p> 1:
        raise ValueError("probability must be between 0 and 1, not {0}".format(p))

    D = DiGraph(loops=False,multiedges=False)
    D.add_vertices(range(n))
    for i in range(n):
        for j in range(n):
            [IF_MASK]
                D.add_edge(i,j)
                if not D.is_directed_acyclic():
                    D.delete_edge(i,j)
    return Poset(D,cover_relations=False)

def _edge_value(G, edge_attr):


    if edge_attr is None:


        [IF_MASK]
            value = lambda u,v: len(G[u][v])
        else:
            value = lambda u,v: 1

    elif not hasattr(edge_attr, '__call__'):


        if edge_attr == 'weight':

            if G.is_multigraph():
                value = lambda u,v: sum([d.get(edge_attr, 1) for d in G[u][v].values()])
            else:
                value = lambda u,v: G[u][v].get(edge_attr, 1)
        else:

            if G.is_multigraph():
                value = lambda u,v: sum([d[edge_attr] for d in G[u][v].values()])
            else:
                value = lambda u,v: G[u][v][edge_attr]

    else:














        value = edge_attr

    return value

def act(self, view, msg):
    if not self.x:
        self.choose_new_direction(view)

    me = view.get_me()
    my_pos = (mx,my) = me.get_pos()


    for a in view.get_agents():
        if (a.get_team() != me.get_team()):
            msg.send_message((MessageType.ATTACK, mx,my))
            if (me.energy > 2000) :
                spawn_x, spawn_y = self.smart_spawn(me, view)
                return cells.Action(cells.ACT_SPAWN,(mx+spawn_x, my+spawn_y, self))
            return cells.Action(cells.ACT_ATTACK, a.get_pos())


    if (view.get_energy().get(mx, my) > 0) :
        if (me.energy < 50) :
            return cells.Action(cells.ACT_EAT)
        if (me.energy < self.defense and (random.random()>0.3)):
            return cells.Action(cells.ACT_EAT)

    [IF_MASK]
        spawn_x, spawn_y = self.smart_spawn(me, view)
        return cells.Action(cells.ACT_SPAWN,(mx + spawn_x, my + spawn_y, self))


    if (not self.my_plant) :
        plants = view.get_plants()
        if (len(plants) > 0) :
            self.my_plant = plants[0];
    if (self.my_plant and (self.children < 50 or random.random()>0.9)):
        self.children += 1;
        spawn_x, spawn_y = self.smart_spawn(me, view)
        return cells.Action(cells.ACT_SPAWN,(mx + spawn_x, my + spawn_y, self))


    map_size = view.energy_map.width
    if (self.step == 0 and True != self.scout and (random.random()>0.2)) :
        ax = 0;
        ay = 0;
        best = view.energy_map.width + view.energy_map.height;
        message_count = len(msg.get_messages());
        for m in msg.get_messages():
            (type, ox,oy) = m
            if (type == MessageType.ATTACK) :
                dist = max(abs(mx-ax),abs(my-ay))
                if dist < best:
                    ax = ox
                    ay = oy
                    best = dist
        if (ax != 0 and ay != 0) :
            self.defense = 2000
            self.x = ax - mx
            self.y = ay - my
            if (message_count > 1) :

                agent_offset = random.randrange(1, 50)
                if (self.x > 0) :
                    self.x += agent_offset
                else :
                    self.x -= agent_offset
                if (self.y > 0) :
                    self.y += agent_offset
                else :
                    self.y -= agent_offset

            if (self.x == 0 and self.y == 0) :
                self.choose_new_direction(view)
            self.step = random.randrange(3, 10);


    if mx <= 0 or mx >= map_size-1 or my <= 0 or my >= map_size-1 :
        self.choose_new_direction(view)


    if (self.step > 0):
        self.step -= 1;


    return cells.Action(cells.ACT_MOVE,(mx+self.x+random.randrange(-1,1),my+self.y+random.randrange(-1,1)))

def copy_template(template_name, copy_to):

    import django_extensions
    import re
    import shutil

    template_dir = os.path.join(django_extensions.__path__[0], 'conf', template_name)


    for d, subdirs, files in os.walk(template_dir):
        relative_dir = d[len(template_dir)+1:]
        if relative_dir and not os.path.exists(os.path.join(copy_to, relative_dir)):
            os.mkdir(os.path.join(copy_to, relative_dir))
        for i, subdir in enumerate(subdirs):
            if subdir.startswith('.'):
                del subdirs[i]
        for f in files:
            if f.endswith('.pyc') or f.startswith('.DS_Store'):
                continue
            path_old = os.path.join(d, f)
            path_new = os.path.join(copy_to, relative_dir, f)
            [IF_MASK]
                path_new = os.path.join(copy_to, relative_dir, f)
                if os.path.exists(path_new):
                    continue
            path_new = path_new.rstrip(".tmpl")
            fp_old = open(path_old, 'r')
            fp_new = open(path_new, 'w')
            fp_new.write(fp_old.read())
            fp_old.close()
            fp_new.close()
            try:
                shutil.copymode(path_old, path_new)
                _make_writeable(path_new)
            except OSError:
                sys.stderr.write(style.NOTICE("Notice: Couldn't set permission bits on %s. You're probably using an uncommon filesystem setup. No problem.\n" % path_new))

