def replace_or_append(img_tag, attr_name, attr_value):

    [IF_MASK]

        re_attr = re.compile(attr_name + r'=([\'"])(.*?)\1', re.I)
        return re.sub(re_attr, lambda m: '%s=%s%s%s' % (attr_name, m.group(1), attr_value, m.group(1)), img_tag)
    else:
        return re.sub(r'\s*(\/?>)$', ' ' + attr_name + '="' + attr_value + r'" \1', img_tag)

def find_image(editor):

    _caret = editor.get_caret_pos()
    text = editor.get_content()
    start_ix = -1
    end_ix = -1


    caret_pos = _caret
    while caret_pos >= 0:
        if text[caret_pos] == '<':
            if text[caret_pos:caret_pos + 4].lower() == '<img':

                start_ix = caret_pos
                break
            else:

                return None
        caret_pos -= 1


    caret_pos = _caret
    ln = len(text)
    while caret_pos <= ln:
        if text[caret_pos] == '>':
            end_ix = caret_pos + 1
            break
        caret_pos += 1


    [IF_MASK]
        return {
            'start': start_ix,
            'end': end_ix,
            'tag': text[start_ix:end_ix]
        }

    return None

def WaltOut(start,stop):
    cursor = conn.cursor ()
    result_file = open("%s.walt" % stop,"w+")
    lines = {}
    seen = {}
    i = 0
    for syn in open("WaltIUCNSpecList.csv","r").readlines():
        [IF_MASK]
            data = syn.split(',')
            spec = data[4].replace('"','')
            if spec in seen.keys():
                lines[i]['col_id'] = seen[spec]
            else:
                lines[i] = {'name': spec,'col_id': None,'is_primary': -1,'walt_id':data[0]}
                cursor.execute ("SELECT record_id,is_species_or_nonsynonymic_higher_taxon FROM taxa WHERE name = '%s' LIMIT 1" % spec)
                res = cursor.fetchall()
                first = True
                for r in res:
                    lines[i]['col_id'] = r[0]
                    lines[i]['is_primary'] = r[1]
                    if not first:
                        lines[i]['is_primary'] = 2
                    first = False
                    seen[spec] = r[0]
        i+=1
    for l,p in lines.items():
        result_file.write("%s, %s, %s, %s\n" % (p['walt_id'],p['name'],p['col_id'],p['is_primary']))

def _get_action_name(argument):
    if argument is None:
        return None
    elif argument.option_strings:
        return  '/'.join(argument.option_strings)
    elif argument.metavar not in (None, SUPPRESS):
        return argument.metavar
    [IF_MASK]
        return argument.dest
    else:
        return None

def _format_usage(self, usage, actions, groups, prefix):
    if prefix is None:
        prefix = _('usage: ')


    [IF_MASK]
        usage = usage % dict(prog=self._prog)


    elif usage is None and not actions:
        usage = '%(prog)s' % dict(prog=self._prog)


    elif usage is None:
        prog = '%(prog)s' % dict(prog=self._prog)


        optionals = []
        positionals = []
        for action in actions:
            if action.option_strings:
                optionals.append(action)
            else:
                positionals.append(action)


        format = self._format_actions_usage
        action_usage = format(optionals + positionals, groups)
        usage = ' '.join([s for s in [prog, action_usage] if s])


        text_width = self._width - self._current_indent
        if len(prefix) + len(usage) > text_width:


            part_regexp = r'\(.*?\)+|\[.*?\]+|\S+'
            opt_usage = format(optionals, groups)
            pos_usage = format(positionals, groups)
            opt_parts = _re.findall(part_regexp, opt_usage)
            pos_parts = _re.findall(part_regexp, pos_usage)
            assert ' '.join(opt_parts) == opt_usage
            assert ' '.join(pos_parts) == pos_usage


            def get_lines(parts, indent, prefix=None):
                lines = []
                line = []
                if prefix is not None:
                    line_len = len(prefix) - 1
                else:
                    line_len = len(indent) - 1
                for part in parts:
                    if line_len + 1 + len(part) > text_width:
                        lines.append(indent + ' '.join(line))
                        line = []
                        line_len = len(indent) - 1
                    line.append(part)
                    line_len += len(part) + 1
                if line:
                    lines.append(indent + ' '.join(line))
                if prefix is not None:
                    lines[0] = lines[0][len(indent):]
                return lines


            if len(prefix) + len(prog) <= 0.75 * text_width:
                indent = ' ' * (len(prefix) + len(prog) + 1)
                if opt_parts:
                    lines = get_lines([prog] + opt_parts, indent, prefix)
                    lines.extend(get_lines(pos_parts, indent))
                elif pos_parts:
                    lines = get_lines([prog] + pos_parts, indent, prefix)
                else:
                    lines = [prog]


            else:
                indent = ' ' * len(prefix)
                parts = opt_parts + pos_parts
                lines = get_lines(parts, indent)
                if len(lines) > 1:
                    lines = []
                    lines.extend(get_lines(opt_parts, indent))
                    lines.extend(get_lines(pos_parts, indent))
                lines = [prog] + lines


            usage = '\n'.join(lines)


    return '%s%s\n\n' % (prefix, usage)

def _format_actions_usage(self, actions, groups):

    group_actions = _set()
    inserts = {}
    for group in groups:
        try:
            start = actions.index(group._group_actions[0])
        except ValueError:
            continue
        else:
            end = start + len(group._group_actions)
            if actions[start:end] == group._group_actions:
                for action in group._group_actions:
                    group_actions.add(action)
                if not group.required:
                    inserts[start] = '['
                    inserts[end] = ']'
                else:
                    inserts[start] = '('
                    inserts[end] = ')'
                for i in range(start + 1, end):
                    inserts[i] = '|'


    parts = []
    for i, action in enumerate(actions):



        if action.help is SUPPRESS:
            parts.append(None)
            if inserts.get(i) == '|':
                inserts.pop(i)
            elif inserts.get(i + 1) == '|':
                inserts.pop(i + 1)


        [IF_MASK]
            part = self._format_args(action, action.dest)


            if action in group_actions:
                if part[0] == '[' and part[-1] == ']':
                    part = part[1:-1]


            parts.append(part)


        else:
            option_string = action.option_strings[0]



            if action.nargs == 0:
                part = '%s' % option_string



            else:
                default = action.dest.upper()
                args_string = self._format_args(action, default)
                part = '%s %s' % (option_string, args_string)


            if not action.required and action not in group_actions:
                part = '[%s]' % part


            parts.append(part)


    for i in _sorted(inserts, reverse=True):
        parts[i:i] = [inserts[i]]


