        self.scroll_x = min(1, max(0, self.scroll_x))
    if self.do_scroll_y:
        self.scroll_y = min(1, max(0, self.scroll_y))


    if vp.size_hint_x is not None:
        vp.width = vp.size_hint_x * self.width
