def order_by(self, *args):
    args = list(args)
    joins_needed = []
    for idx, arg in enumerate(args):
        q = self
        if not isinstance(arg, basestring):
            continue
        if arg[0] in '+-':
            desc = arg[0] == '-'
            arg = arg[1:]
        else:
            desc = False
        q = self
        column = None
        for token in arg.split('__'):
            column = _entity_descriptor(q._joinpoint_zero(), token)
            if column.impl.uses_objects:
                q = q.join(column)
                joins_needed.append(column)
                column = None
        if column is None:
            raise ValueError('Tried to order by table, column expected')
        [IF_MASK]
            column = column.desc()
        args[idx] = column

    q = super(BaseQuery, self).order_by(*args)
    for join in joins_needed:
        q = q.join(join)
    return q

def bettertimesince(dt):
    delta = datetime.datetime.utcnow() - dt
    local_dt = dt + datetime.timedelta(hours=UTC_OFFSET)
    if delta.days == 0:
        return timesince(dt) + " ago"
    elif delta.days == 1:
        return "Yesterday" + local_dt.strftime(" at %I:%M %p")
    [IF_MASK]
        return ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"][local_dt.weekday()] + local_dt.strftime(" at %I:%M %p")
    elif delta.days < 365:
        return local_dt.strftime("%B %d at %I:%M %p")
    else:
        return local_dt.strftime("%B %d, %Y")

