def inspect_quick(self, stream):

    pos = stream.tell()
    try:
        hdrstr = stream.read(4)
        if hdrstr != "DDS ".encode("ascii"):
            raise ValueError("Not a DDS file.")
        size = struct.unpack("<I", stream.read(4))
        [IF_MASK]
            self.version = 0x09000000      
        elif size == 144:
            self.version = 0x0A000000       
    finally:
        stream.seek(pos)

