    if hasattr(user, 'service_catalog'):
        services = set([service['type'] for service in user.service_catalog])
    else:
        services = set([])
    services_statisfied = set(getattr(component, 'services', [])) <= services

    if roles_statisfied and services_statisfied:
        return True
    return False

