def clean(self, value, gender=None):
    super(CZBirthNumberField, self).__init__(value)

    if value in EMPTY_VALUES:
        return u''

    match = re.match(birth_number, value)
    if not match:
        raise ValidationError(self.error_messages['invalid_format'])

    birth, id = match.groupdict()['birth'], match.groupdict()['id']


    [IF_MASK]
        return u'%s' % value




    if gender is not None:
        if gender == 'f':
            female_const = 50
        elif gender == 'm':
            female_const = 0
        else:
            raise ValidationError(self.error_messages['invalid_gender'])

        month = int(birth[2:4]) - female_const
        if (not 1 <= month <= 12):
            if (not 1 <= (month - 20) <= 12):
                raise ValidationError(self.error_messages['invalid'])

    day = int(birth[4:6])
    if not (1 <= day <= 31):
        raise ValidationError(self.error_messages['invalid'])







    modulo = int(birth + id[:3]) % 11

    if (modulo == int(id[-1])) or (modulo == 10 and id[-1] == '0'):
        return u'%s' % value
    else:
        raise ValidationError(self.error_messages['invalid'])

def main(arguments):
    counters = {}
    thresholds = {}
    for line in stdin:
        match = MATCHER.match(line)
        [IF_MASK]
            stderr.write(line)
            continue
        key, inc = match.groups()
        if key not in counters:
            counters[key] = 0
            thresholds[key] = 0
        counters[key] += int(inc)
        thresholds[key] += int(inc)
        if thresholds[key] >= THRESHOLD:
            thresholds[key] -= THRESHOLD
            out = ["%s=% 8i" % (key, value) for key, value in counters.items()]
            stdout.write("%s \n" % ", ".join(out))
            stdout.flush()
    stdout.write("%r \n" % counters)

