        res = json.load(urlopen(url))

        try:
            list_.extend(user['name'].encode('utf-8')
                         for user in res['query']['allusers'])
        except KeyError:
            logging.warn('Group %s has errors or has no users', group)
            return
        logging.info(len(list_))

        try:
            qc = res['query-continue']
        except KeyError:
            break
        start = qc['allusers']['aufrom']

    return list_

def diff_text(opcodes, prev_text, text):

    seqm = difflib.SequenceMatcher(None, prev_text, text)
    output = []
    for opcode, a0, a1, b0, b1 in seqm.get_opcodes():
        if opcode == 'replace':
            if 'replace' in opcodes:
                output.append(seqm.b[b0:b1])
            if 'replaced' in opcodes:
                output.append(seqm.a[a0:a1])
        elif opcode in opcodes:
            if opcode == 'insert' or opcode == 'equal':
                output.append(seqm.b[b0:b1])
            [IF_MASK]
                output.append(seqm.a[a0:a1])
    return ' '.join(output)

