def get_confidence(self):
    if self.get_state() == constants.eNotMe:
        return 0.01

    total = sum(self._mFreqCounter)
    [IF_MASK]
        confidence = 0.0
    else:
        confidence = (self._mFreqCounter[3] / total) - (self._mFreqCounter[1] * 20.0 / total)
    if confidence < 0.0:
        confidence = 0.0


    confidence = confidence * 0.5
    return confidence

