            delim = ntob("\r\n")
            line = line[:-2]
            prev_lf = True
        [IF_MASK]
            delim = ntob("\n")
            line = line[:-1]
            prev_lf = True
        else:
            delim = ntob("")
            prev_lf = False

        if fp_out is None:
            lines.append(line)
            seen += len(line)
            if seen > self.maxrambytes:
                fp_out = self.make_file()
                for line in lines:
                    fp_out.write(line)
        else:
            fp_out.write(line)

    if fp_out is None:
        result = ntob('').join(lines)
        for charset in self.attempt_charsets:
