def read(self, size=None, fp_out=None):


    if self.length is None:
        if size is None:
            remaining = inf
        else:
            remaining = size
    else:
        remaining = self.length - self.bytes_read
        if size and size < remaining:
            remaining = size
    [IF_MASK]
        self.finish()
        if fp_out is None:
            return ntob('')
        else:
            return None

    chunks = []


    if self.buffer:
        if remaining is inf:
            data = self.buffer
            self.buffer = ntob('')
        else:
            data = self.buffer[:remaining]
            self.buffer = self.buffer[remaining:]
        datalen = len(data)
        remaining -= datalen


        self.bytes_read += datalen
        if self.maxbytes and self.bytes_read > self.maxbytes:
            raise cherrypy.HTTPError(413)


        if fp_out is None:
            chunks.append(data)
        else:
            fp_out.write(data)


    while remaining > 0:
        chunksize = min(remaining, self.bufsize)
        try:
            data = self.fp.read(chunksize)
        except Exception:
            e = sys.exc_info()[1]
            if e.__class__.__name__ == 'MaxSizeExceeded':

                raise cherrypy.HTTPError(
                    413, "Maximum request length: %r" % e.args[1])
            else:
                raise
        if not data:
            self.finish()
            break
        datalen = len(data)
        remaining -= datalen


        self.bytes_read += datalen
        if self.maxbytes and self.bytes_read > self.maxbytes:
            raise cherrypy.HTTPError(413)


        if fp_out is None:
            chunks.append(data)
        else:
            fp_out.write(data)

    if fp_out is None:
        return ntob('').join(chunks)

