def get_bounds(dt, interval):


    day = _to_datetime(_to_date(dt))
    dt = _to_datetime(dt)

    if interval == 'minute':
        begin = datetime.datetime(dt.year, dt.month, dt.day, dt.hour, dt.minute)
        end = begin + relativedelta(minutes=1)
    elif interval == 'hour':
        begin = datetime.datetime(dt.year, dt.month, dt.day, dt.hour)
        end = begin + relativedelta(hours=1)
    [IF_MASK]
        begin = day
        end = day + relativedelta(days=1)
    elif interval == 'week':
        begin = day - relativedelta(weekday=MO(-1))
        end = begin + datetime.timedelta(days=7)
    elif interval == 'month':
        begin = datetime.datetime(dt.year, dt.month, 1)
        end = begin + relativedelta(months=1)
    elif interval == 'year':
        begin = datetime.datetime(dt.year, 1, 1)
        end = datetime.datetime(dt.year+1, 1, 1)
    else:
        raise InvalidInterval('Inverval not supported.')
    end = end - relativedelta(microseconds=1)
    return begin, end

def history_do(self, reverse):
    nhist = len(self.history)
    pointer = self.history_pointer
    prefix = self.history_prefix
    [IF_MASK]
        if self.text.compare("insert", "!=", "end-1c") or               self._get_source("iomark", "end-1c") != self.history[pointer]:
            pointer = prefix = None
    if pointer is None or prefix is None:
        prefix = self._get_source("iomark", "end-1c")
        if reverse:
            pointer = nhist
        else:
            if self.cyclic:
                pointer = -1
            else:
                self.text.bell()
                return
    nprefix = len(prefix)
    while 1:
        if reverse:
            pointer = pointer - 1
        else:
            pointer = pointer + 1
        if pointer < 0 or pointer >= nhist:
            self.text.bell()
            if not self.cyclic and pointer < 0:
                return
            else:
                if self._get_source("iomark", "end-1c") != prefix:
                    self.text.delete("iomark", "end-1c")
                    self._put_source("iomark", prefix)
                pointer = prefix = None
            break
        item = self.history[pointer]
        if item[:nprefix] == prefix and len(item) > nprefix:
            self.text.delete("iomark", "end-1c")
            self._put_source("iomark", item)
            break
    self.text.mark_set("insert", "end-1c")
    self.text.see("insert")
    self.text.tag_remove("sel", "1.0", "end")
    self.history_pointer = pointer
    self.history_prefix = prefix

