def setup(request):
    if not request.facebook.uid:
        return HttpResponseRedirect(reverse('auth_login')+"?next="+request.GET.get('next',''))

    if request.method == "POST":
        if request.POST.get('next',False) and request.POST['next']:
            next = request.POST['next']
        else:
            next = getattr(settings,'LOGIN_REDIRECT_URL','/')

        profile = FacebookProfile(facebook_id=request.facebook.uid)

        if request.POST.get('facebook_only',False):
            if not User.objects.filter(username=profile.first_name):
                user = User(
                    username=profile.first_name,
                    password=sha.new(str(random.random())).hexdigest()[:8]
                )
                user.save()

            else:
                user = User( 
                    username = str(request.facebook.uid),
                    password = sha.new( str(random.random())).hexdigest()[:8] 
                )
                user.save()

            [IF_MASK]
                point = Point(point=request.POST['map'],
                        owner=user, content_type = ContentType.objects.get_for_model(user),
                        object_id=user.id)
                point.save()

            profile.user = user
            profile.save()
            logging.info("FBC: Added user and profile for %s!" % request.facebook.uid)
            user = authenticate(request=request)
            login(request, user)
            return HttpResponseRedirect(next)

        form = AuthenticationForm(data=request.POST)

        if form.is_valid():
            user = form.get_user()
            logging.debug("FBC: Trying to setup FB: %s, %s" % (user,profile))
            if user is not None and user.is_active:
                if request.POST['map']:
                    point = Point(point=request.POST['map'],
                          owner=user, content_type = ContentType.objects.get_for_model(user),
                          object_id=user.id)
                    point.save()

                profile.user = user
                profile.save()
                logging.info("FBC: Attached facebook profile %s to user %s!" % (profile.facebook_id,user))
                login(request, user)
                return HttpResponseRedirect(next)
        else:
            user = User()
            user.facebook_profile = profile

    elif request.user.is_authenticated():
        profile = FacebookProfile(facebook_id=request.facebook.uid)
        profile.user = request.user
        profile.save()
        logging.info("FBC: Attached facebook profile %s to user %s!" % (profile.facebook_id,profile.user.id))
        return HttpResponseRedirect('/')

    else:
        user = User()
        user.facebook_profile = FacebookProfile(facebook_id=request.facebook.uid)
        next = request.GET.get('next','')
        form = AuthenticationForm(request)

    return render_to_response(
        'facebook/setup.html',
        {"user":user,
         "form":form,
         "next":next},
        context_instance=RequestContext(request))

def extract_nodes(nodes, keywords, comment_tags, options):

    translator_comments = []
    in_translator_comments = False

    for node in nodes:
        child_nodes = None
        if in_translator_comments and isinstance(node, parsetree.Text) and                not node.content.strip():

            continue

        if isinstance(node, parsetree.Comment):
            value = node.text.strip()
            if in_translator_comments:
                translator_comments.extend(_split_comment(node.lineno, value))
                continue
            for comment_tag in comment_tags:
                if value.startswith(comment_tag):
                    in_translator_comments = True
                    translator_comments.extend(_split_comment(node.lineno,
                                                              value))
            continue

        [IF_MASK]
            code = node.function_decl.code
            child_nodes = node.nodes
        elif isinstance(node, parsetree.CallTag):
            code = node.code.code
            child_nodes = node.nodes
        elif isinstance(node, parsetree.PageTag):
            code = node.body_decl.code
        elif isinstance(node, parsetree.CallNamespaceTag):
            attribs = ', '.join(['%s=%s' % (key, val)
                                 for key, val in node.attributes.iteritems()])
            code = '{%s}' % attribs
            child_nodes = node.nodes
        elif isinstance(node, parsetree.ControlLine):
            if node.isend:
                translator_comments = []
                in_translator_comments = False
                continue
            code = node.text
        elif isinstance(node, parsetree.Code):

            translator_comments = []
            in_translator_comments = False

            code = node.code.code
        elif isinstance(node, parsetree.Expression):
            code = node.code.code
        else:
            translator_comments = []
            in_translator_comments = False
            continue


        if translator_comments and                translator_comments[-1][0] < node.lineno - 1:
            translator_comments = []
        else:
            translator_comments =                [comment[1] for comment in translator_comments]

        if isinstance(code, unicode):
            code = code.encode('ascii', 'backslashreplace')
        code = StringIO(code)
        for lineno, funcname, messages, python_translator_comments                in extract_python(code, keywords, comment_tags, options):
            yield (node.lineno + (lineno - 1), funcname, messages,
                   translator_comments + python_translator_comments)

        translator_comments = []
        in_translator_comments = False

        if child_nodes:
            for extracted in extract_nodes(child_nodes, keywords, comment_tags,
                                           options):
                yield extracted

