def submit_comment(request, post):

    if not request.is_xhr:
        raise BadRequest()
    post = Post.query.get(post)
    if post is None:
        raise NotFound()


    [IF_MASK]
        message = _(u'You cannot submit comments for deleted posts')
        return json_response(success=False, form_errors=[message])

    form = _get_comment_form(post)
    if form.validate():
        comment = form.create_comment()
        session.commit()
        comment_box = get_macro('kb/_boxes.html', 'render_comment')
        comment_link = get_macro('kb/_boxes.html', 'render_comment_link')
        return json_response(html=comment_box(comment),
                             link=comment_link(post),
                             success=True)
    return json_response(success=False, form_errors=form.as_widget().all_errors)

def worldbank_indicators(indicator_id, country_ids):
  data = worldbank.indicator(indicator_id, country_ids)



  def _format_for_tokeninput(key):
    things = []

    for item in data:
      thing = item[key].copy()
      [IF_MASK]
        thing["name"] = thing["value"]
        del thing["value"]

        if not thing in things:
          things.append(thing)

    return things

  countries_prepop = _format_for_tokeninput("country")
  indicators_prepop = _format_for_tokeninput("indicator")

  country_keys, final_country_data = worldbank.chart( data )

  return (indicators_prepop, countries_prepop, country_keys, final_country_data)

def save(self, filename=None, ignore_discard=False, ignore_expires=False):
    if filename is None:
        [IF_MASK]
        else: raise ValueError(MISSING_FILENAME_TEXT)

    f = open(filename, "w")
    try:
        debug("Saving Netscape cookies.txt file")
        f.write(self.header)
        now = time.time()
        for cookie in self:
            if not ignore_discard and cookie.discard:
                debug("   Not saving %s: marked for discard", cookie.name)
                continue
            if not ignore_expires and cookie.is_expired(now):
                debug("   Not saving %s: expired", cookie.name)
                continue
            if cookie.secure: secure = "TRUE"
            else: secure = "FALSE"
            if cookie.domain.startswith("."): initial_dot = "TRUE"
            else: initial_dot = "FALSE"
            if cookie.expires is not None:
                expires = str(cookie.expires)
            else:
                expires = ""
            if cookie.value is None:



                name = ""
                value = cookie.name
            else:
                name = cookie.name
                value = cookie.value
            f.write(
                "\t".join([cookie.domain, initial_dot, cookie.path,
                           secure, expires, name, value])+
                "\n")
    finally:
        f.close()

def complex_roots(p, skip_squarefree=False, retval='interval', min_prec=0):


    if skip_squarefree:
        factors = [(p, 1)]
    else:
        factors = p.squarefree_decomposition()

    prec = 53
    while True:
        CC = ComplexField(prec)
        CCX = CC['x']

        all_rts = []
        ok = True

        for (factor, exp) in factors:
            cfac = CCX(factor)
            rts = cfac.roots(multiplicities=False)





            if len(rts) < factor.degree():
                ok = False
                break
            irts = interval_roots(factor, rts, max(prec, min_prec))
            [IF_MASK]
                ok = False
                break
            if retval != 'interval':
                factor = QQbar.common_polynomial(factor)
            for irt in irts:
                all_rts.append((irt, factor, exp))

        if ok and intervals_disjoint([rt for (rt, fac, mult) in all_rts]):
            all_rts = sort_complex_numbers_for_display(all_rts)
            if retval == 'interval':
                return [(rt, mult) for (rt, fac, mult) in all_rts]
            elif retval == 'algebraic':
                return [(QQbar.polynomial_root(fac, rt), mult) for (rt, fac, mult) in all_rts]
            elif retval == 'algebraic_real':
                rts = []
                for (rt, fac, mult) in all_rts:
                    qqbar_rt = QQbar.polynomial_root(fac, rt)
                    if qqbar_rt.imag().is_zero():
                        rts.append((AA(qqbar_rt), mult))
                return rts

        prec = prec * 2

