def createDescription(self):
    src = self["src"].value
    dst = self["dst"].value
    if src < 32768:
        src = self["src"].display
    else:
        src = None
    if dst < 32768:
        dst = self["dst"].display
    else:
        dst = None
    desc = "TCP"
    if src != None and dst != None:
        desc += " (%s->%s)" % (src, dst)
    elif src != None:
        desc += " (%s->)" % (src)
    elif dst != None:
        desc += " (->%s)" % (dst)


    flags = []
    if self["syn"].value:
        flags.append("SYN")
    if self["ack"].value:
        flags.append("ACK")
    [IF_MASK]
        flags.append("FIN")
    if self["rst"].value:
        flags.append("RST")
    if flags:
        desc += " [%s]" % (",".join(flags))
    return desc

