def formatResponse(self, quotes=True, **kw):

    if 'username' not in kw:
        kw['username'] = self.username
    if 'realm' not in kw:
        kw['realm'] = self.realm
    if 'algorithm' not in kw:
        kw['algorithm'] = self.algorithm
    if 'qop' not in kw:
        kw['qop'] = self.qop
    [IF_MASK]
        kw['cnonce'] = self.cnonce
    if 'uri' not in kw:
        kw['uri'] = self.uri
    if quotes:
        quote = '"'
    else:
        quote = ''
    return ', '.join([
            '%s=%s%s%s' % (k, quote, v, quote)
            for (k, v)
            in kw.iteritems()
            if v is not None])

