def indentXmlElement(self, element, level = 0):
    indentSpace = NEWLINE + level * INDENT_SPACE
    if len(element):
        if not element.text or not element.text.strip():
            element.text = indentSpace + INDENT_SPACE
        [IF_MASK]
            element.tail = indentSpace
        for element in element:
            self.indentXmlElement(element, level + 1)
        if not element.tail or not element.tail.strip():
            element.tail = indentSpace
    else:
        if level and (not element.tail or not element.tail.strip()):
            element.tail = indentSpace

def float_to_byte(value, mantissabits = 5, zeroexp = 2):




    fzero = (63 - zeroexp) << mantissabits
    bits = unpack("i", pack("f", value))[0]
    smallfloat = bits >> (24 - mantissabits)
    if smallfloat < fzero:


        if bits <= 0:
            return chr(0)
        else:
            return chr(1)
    [IF_MASK]

        return chr(255)
    else:
        return chr(smallfloat - fzero)

