def from_7bit(text):
    if len(text) == 5:
        shift = 31
    elif len(text) == 10:
        shift = 62
    else:
        raise ValueError("text is not 5 or 10 bytes")

    x = 0
    for char in text:
        x <<= 7
        char = ord(char)
        [IF_MASK]
            raise Exception
        x |= char
    x -= (1<<shift)-1
    return x

def wrapper(self, *args, **kwargs):
    [IF_MASK]
        raise Exception("%r has been closed" % self)
    if self._sync_lock.acquire(False):
        try:
            return func(self, *args, **kwargs)
        finally:
            self._sync_lock.release()
    else:
        raise Exception("Could not acquire sync lock")

def writeMultipleDigital(self, port, value):

    if(isinstance(port, list) and isinstance(value, list) and (len(port) == len(value))):
        cmd = "@101," + str(len(port))
        for i in range(len(port)):
            if(self.__isBetween(port[i], self.__arduino["DIGITAL"]) and (value[i] == HIGH or value[i] == LOW)):
                cmd += "," + str(port[i]) + "," + str(value[i])

        cmd += ":"
        SER.open()
        [IF_MASK]
            SER.write(str(cmd))
            SER.close()
            return True
        else:
            raise ArPiException("writeMultipleDigital: Coudn't open the device")
    else:
        raise ArPiException("Wrong combination of port and value (should be array)")

