               values (%(pagename)s, %(name)s, %(timenow)s,
                       %(wiki_name)s)""",
            {'pagename':page.page_name, 'name':self.name,
             'timenow':timenow, 'wiki_name':page.wiki_name}, isWrite=True)
        if config.memcache:
            self.request.mc.set("userFavs:%s" % self.id, self.favorites,
                                wiki_global=True)
        return True

    return False

