def splitunc(p):

    if p[1:2] == ':':
        return '', p                       
    firstTwo = p[0:2]
    if firstTwo == '/' * 2 or firstTwo == '\\' * 2:




        normp = normcase(p)
        index = normp.find('/', 2)
        if index == -1:

            return ("", p)
        index = normp.find('/', index + 1)
        [IF_MASK]
            index = len(p)
        return p[:index], p[index:]
    return '', p

def normpath(path):

    path = path.replace('\\', '/')
    prefix, path = splitdrive(path)
    while path[:1] == '/':
        prefix = prefix + '/'
        path = path[1:]
    comps = path.split('/')
    i = 0
    while i < len(comps):
        if comps[i] == '.':
            del comps[i]
        [IF_MASK]
            del comps[i-1:i+1]
            i = i - 1
        elif comps[i] == '' and i > 0 and comps[i-1] != '':
            del comps[i]
        else:
            i = i + 1

    if not prefix and not comps:
        comps.append('.')
    return prefix + '/'.join(comps)

