def _detectEncoding(self, xml_data, is_html=False):

    xml_encoding = sniffed_xml_encoding = None
    try:
        if xml_data[:4] == b'\x4c\x6f\xa7\x94':

            xml_data = self._ebcdic_to_ascii(xml_data)
        elif xml_data[:4] == b'\x00\x3c\x00\x3f':

            sniffed_xml_encoding = 'utf-16be'
            xml_data = unicode(xml_data, 'utf-16be').encode('utf-8')
        elif (len(xml_data) >= 4) and (xml_data[:2] == b'\xfe\xff')                     and (xml_data[2:4] != b'\x00\x00'):

            sniffed_xml_encoding = 'utf-16be'
            xml_data = unicode(xml_data[2:], 'utf-16be').encode('utf-8')
        [IF_MASK]

            sniffed_xml_encoding = 'utf-16le'
            xml_data = unicode(xml_data, 'utf-16le').encode('utf-8')
        elif (len(xml_data) >= 4) and (xml_data[:2] == b'\xff\xfe') and                     (xml_data[2:4] != b'\x00\x00'):

            sniffed_xml_encoding = 'utf-16le'
            xml_data = unicode(xml_data[2:], 'utf-16le').encode('utf-8')
        elif xml_data[:4] == b'\x00\x00\x00\x3c':

            sniffed_xml_encoding = 'utf-32be'
            xml_data = unicode(xml_data, 'utf-32be').encode('utf-8')
        elif xml_data[:4] == b'\x3c\x00\x00\x00':

            sniffed_xml_encoding = 'utf-32le'
            xml_data = unicode(xml_data, 'utf-32le').encode('utf-8')
        elif xml_data[:4] == b'\x00\x00\xfe\xff':

            sniffed_xml_encoding = 'utf-32be'
            xml_data = unicode(xml_data[4:], 'utf-32be').encode('utf-8')
        elif xml_data[:4] == b'\xff\xfe\x00\x00':

            sniffed_xml_encoding = 'utf-32le'
            xml_data = unicode(xml_data[4:], 'utf-32le').encode('utf-8')
        elif xml_data[:3] == b'\xef\xbb\xbf':

            sniffed_xml_encoding = 'utf-8'
            xml_data = unicode(xml_data[3:], 'utf-8').encode('utf-8')
        else:
            sniffed_xml_encoding = 'ascii'
            pass
    except:
        xml_encoding_match = None
    xml_encoding_match = xml_encoding_re.match(xml_data)
    if not xml_encoding_match and is_html:
        xml_encoding_match = html_meta_re.search(xml_data)
    if xml_encoding_match is not None:
        xml_encoding = xml_encoding_match.groups()[0].decode(
            'ascii').lower()
        if is_html:
            self.declared_html_encoding = xml_encoding
        if sniffed_xml_encoding and               (xml_encoding in ('iso-10646-ucs-2', 'ucs-2', 'csunicode',
                             'iso-10646-ucs-4', 'ucs-4', 'csucs4',
                             'utf-16', 'utf-32', 'utf_16', 'utf_32',
                             'utf16', 'u16')):
            xml_encoding = sniffed_xml_encoding
    return xml_data, xml_encoding, sniffed_xml_encoding

def detwingle(cls, in_bytes, main_encoding="utf8",
              embedded_encoding="windows-1252"):

    if embedded_encoding.replace('_', '-').lower() not in (
        'windows-1252', 'windows_1252'):
        raise NotImplementedError(
            "Windows-1252 and ISO-8859-1 are the only currently supported "
            "embedded encodings.")

    [IF_MASK]
        raise NotImplementedError(
            "UTF-8 is the only currently supported main encoding.")

    byte_chunks = []

    chunk_start = 0
    pos = 0
    while pos < len(in_bytes):
        byte = in_bytes[pos]
        if not isinstance(byte, int):

            byte = ord(byte)
        if (byte >= cls.FIRST_MULTIBYTE_MARKER
            and byte <= cls.LAST_MULTIBYTE_MARKER):


            for start, end, size in cls.MULTIBYTE_MARKERS_AND_SIZES:
                if byte >= start and byte <= end:
                    pos += size
                    break
        elif byte >= 0x80 and byte in cls.WINDOWS_1252_TO_UTF8:


            byte_chunks.append(in_bytes[chunk_start:pos])



            byte_chunks.append(cls.WINDOWS_1252_TO_UTF8[byte])
            pos += 1
            chunk_start = pos
        else:

            pos += 1
    if chunk_start == 0:

        return in_bytes
    else:

        byte_chunks.append(in_bytes[chunk_start:])
    return b''.join(byte_chunks)

