def get_cover_path(self, song):

    ''' You don't need to override this'''

    artist = song.artist.encode('utf8')
    album = song.album.encode('utf8')

    if artist == "?":
        artist = ""

    [IF_MASK]
        album = ""

    if len(artist) == 0 and len(album) == 0:
        return None

    if (os.name != 'nt'):
        home_dir = os.path.expanduser('~')
    else:
        home_dir = os.path.expanduser("~").decode(
            sys.getfilesystemencoding())

    cover_art_path = os.path.join(home_dir, '.covers', '')

    if not os.path.exists(cover_art_path):
        os.makedirs(cover_art_path)



    image_path = cover_art_path + artist + '-' + album + '.jpg'



    if os.path.exists(image_path):

        return image_path



    url = "http://www.albumart.org/index.php?srchkey=" +            urllib.quote_plus(artist) + "+" + urllib.quote_plus(album) +            "&itempage=1&newsearch=1&searchindex=Music"

    albumart = urllib.urlopen(url).read()
    image_url = ""

    for line in albumart.split("\n"):

        if "http://www.albumart.org/images/zoom-icon.jpg" in line:
            image_url = line.partition('src="')[2].partition('"')[0]

        if image_url:
            urllib.urlretrieve(image_url, image_path)
            break

    if os.path.exists(image_path):
        return image_path

    return None

def tarextract(package, fileobj=None, prefix=None, base=None):

    extracted = []
    if fileobj:
        if type(fileobj) == types.StringType: fileobj = cStringIO.StringIO(fileobj)
        tarf = tarfile.open(mode='r|', fileobj=fileobj)
    else: tarf = tarfile.open(package, 'r')
    for tarinfo in tarf:
        if tarinfo.name.startswith('/'): tarinfo.name = tarinfo.name[1:]                  
        [IF_MASK]
            if prefix: tarinfo.name = '/'.join([prefix, tarinfo.name])
            tarf.extract(tarinfo)
            extracted.append(tarinfo.name)
    tarf.close()
    if fileobj:
        try: fileobj.close()
        except: pass
        del fileobj
    return extracted

