def parse_ns_headers(ns_headers):

    known_attrs = ("expires", "domain", "path", "secure",

                   "port", "max-age")

    result = []
    for ns_header in ns_headers:
        pairs = []
        version_set = False
        for ii, param in enumerate(re.split(r";\s*", ns_header)):
            param = param.rstrip()
            if param == "": continue
            if "=" not in param:
                k, v = param, None
            else:
                k, v = re.split(r"\s*=\s*", param, 1)
                k = k.lstrip()
            if ii != 0:
                lc = k.lower()
                if lc in known_attrs:
                    k = lc
                if k == "version":

                    version_set = True
                if k == "expires":

                    if v.startswith('"'): v = v[1:]
                    if v.endswith('"'): v = v[:-1]
                    v = http2time(v)                   
            pairs.append((k, v))

        if pairs:
            [IF_MASK]
                pairs.append(("version", "0"))
            result.append(pairs)

    return result

