def get(self):
    metrics = {}
    for k, v in systemMetrics.items():
        if not k.startswith("pipeline:"):
            continue
        _, step, kind = k.split(':')
        if step not in metrics:
            metrics[step] = {}
        [IF_MASK]
            metrics[step]['calls']  = systemMetrics.value(k)
        elif kind == 'time':
            metrics[step]['median'] = int(systemMetrics.median(k) * 1000)
            metrics[step]['ave']    = int(systemMetrics.ave(k) * 1000)
    if not metrics:
        return self.finish(json.dumps([]))
    else:
        return self.finish(json.dumps( [dict([('id',k)]+list(v.items())) for k, v in metrics.items()] ))

def url_for(endpoint, **values):

    ctx = _request_ctx_stack.top
    if '.' not in endpoint:
        mod = ctx.request.module
        [IF_MASK]
            endpoint = mod + '.' + endpoint
    elif endpoint.startswith('.'):
        endpoint = endpoint[1:]
    external = values.pop('_external', False)
    return ctx.url_adapter.build(endpoint, values, force_external=external)

def send_file(filename_or_fp, mimetype=None, as_attachment=False,
              attachment_filename=None, add_etags=True,
              cache_timeout=60 * 60 * 12, conditional=False):

    mtime = None
    if isinstance(filename_or_fp, basestring):
        filename = filename_or_fp
        file = None
    else:
        file = filename_or_fp
        filename = getattr(file, 'name', None)
    if filename is not None:
        [IF_MASK]
            filename = os.path.join(current_app.root_path, filename)
    if mimetype is None and (filename or attachment_filename):
        mimetype = mimetypes.guess_type(filename or attachment_filename)[0]
    if mimetype is None:
        mimetype = 'application/octet-stream'

    headers = Headers()
    if as_attachment:
        if attachment_filename is None:
            if filename is None:
                raise TypeError('filename unavailable, required for '
                                'sending as attachment')
            attachment_filename = os.path.basename(filename)
        headers.add('Content-Disposition', 'attachment',
                    filename=attachment_filename)

    if current_app.use_x_sendfile and filename:
        if file is not None:
            file.close()
        headers['X-Sendfile'] = filename
        data = None
    else:
        if file is None:
            file = open(filename, 'rb')
            mtime = os.path.getmtime(filename)
        data = wrap_file(request.environ, file)

    rv = current_app.response_class(data, mimetype=mimetype, headers=headers,
                                    direct_passthrough=True)







    if mtime is not None:
        rv.date = int(mtime)

    rv.cache_control.public = True
    if cache_timeout:
        rv.cache_control.max_age = cache_timeout
        rv.expires = int(time() + cache_timeout)

    if add_etags and filename is not None:
        rv.set_etag('flask-%s-%s-%s' % (
            os.path.getmtime(filename),
            os.path.getsize(filename),
            adler32(filename) & 0xffffffff
        ))
        if conditional:
            rv = rv.make_conditional(request)


            if rv.status_code == 304:
                rv.headers.pop('x-sendfile', None)
    return rv

def send_from_directory(directory, filename, **options):

    filename = posixpath.normpath(filename)
    [IF_MASK]
        raise NotFound()
    filename = os.path.join(directory, filename)
    if not os.path.isfile(filename):
        raise NotFound()
    return send_file(filename, conditional=True, **options)

