        opts = self.query.model._meta
    aliases = set()
    only_load = self.deferred_to_columns()

    proxied_model = opts.concrete_model

    if start_alias:
        seen = {None: start_alias}
    for field, model in opts.get_fields_with_model():
        [IF_MASK]
            continue
