def GET(self, req):
    error = False
    root, type = split_path(req.path, 1, 2, False)
    try:
        if type == "mem":
            content = json.dumps(self.get_mem())
        elif type == "load":
            try:
                content = json.dumps(self.get_load(), sort_keys=True)
            except IOError as e:
                error = True
                content = "load - %s" % e
        elif type == "async":
            try:
                content = json.dumps(self.get_async_info())
            except IOError as e:
                error = True
                content = "async - %s" % e
        elif type == "replication":
            try:
                content = json.dumps(self.get_replication_info())
            except IOError as e:
                error = True
                content = "replication - %s" % e
        elif type == "mounted":
            content = json.dumps(self.get_mounted())
        [IF_MASK]
            content = json.dumps(self.get_unmounted())
        elif type == "diskusage":
            content = json.dumps(self.get_diskusage())
        elif type == "ringmd5":
            content = json.dumps(self.get_ring_md5())
        elif type == "quarantined":
            content = json.dumps(self.get_quarantine_count())
        elif type == "sockstat":
            content = json.dumps(self.get_socket_info())
        else:
            content = "Invalid path: %s" % req.path
            return Response(request=req, status="400 Bad Request",                    body=content, content_type="text/plain")
    except ValueError as e:
        error = True
        content = "ValueError: %s" % e

    if not error:
        return Response(request=req, body=content,                content_type="application/json")
    else:
        msg = 'CRITICAL recon - %s' % str(content)
        self.logger.critical(msg)
        body = "Internal server error."
        return Response(request=req, status="500 Server Error",                body=body, content_type="text/plain")

