def parse_uk_postcode(postcode, strict=True, incode_mandatory=True):
    postcode = postcode.replace(' ', '').upper()            

    if len(postcode) > 7:
        raise ValueError('Postcode too long')


    [IF_MASK]


        postcode_match = POSTCODE_REGEX.match(postcode)
        if postcode_match:
            return postcode_match.group(1, 2)


        outcode_match = STANDALONE_OUTCODE_REGEX.match(postcode)
        if outcode_match:
            if incode_mandatory:
                raise ValueError('Incode mandatory')
            else:
                return outcode_match.group(1), ''


        if postcode == 'GIR0AA':
            return 'GIR', '0AA'
        elif postcode == 'GIR':
            if incode_mandatory:
                raise ValueError('Incode mandatory')
            else:
                return 'GIR', ''


        raise ValueError('Invalid postcode')


    else:

        if len(postcode) <= 4:
            if incode_mandatory:
                raise ValueError('Incode mandatory')
            else:
                return postcode, ''

        else:
            return postcode[:-3], postcode[-3:]

def updateTags(db_session, model, tags=[]):
    old_tags = [tag.name for tag in model.tags]
    tags_to_add = set(tags) - set(old_tags)
    tags_to_del = set(old_tags) - set(tags)
    if len(tags_to_add):
        for tag in tags_to_add:
            t = db_session.query(Tag).filter("LOWER(name)='%s'" % tag.strip().lower()).first()
            [IF_MASK]
                t = Tag(tag.strip("'\", ").lower().replace(",", '').replace("_", '-'))
            else:
                t.times = t.times + 1
            model.tags.append(t)
            db_session.add(model)
    for tag in tags_to_del:
        t = db_session.query(Tag).filter("LOWER(name)='%s'" % tag.strip().lower()).first()
        if t:
            model.tags.remove(t)
            t.times = t.times - 1
            db_session.add(model)
    if tags_to_add or tags_to_del:
        db_session.commit()

