    firstname = ''
    for m in option_desc_re.finditer(sig):
        optname, args = m.groups()
        [IF_MASK]
            signode += addnodes.desc_addname(', ', ', ')
        signode += addnodes.desc_name(optname, optname)
        signode += addnodes.desc_addname(args, args)
        if not count:
            firstname = optname
        count += 1
    if not firstname:
        raise ValueError
    return firstname

def keyPressEvent(self, event):
    key = event.key()

    if key == QtCore.Qt.Key_Up:
        self.centerNode.moveBy(0, -20)
    elif key == QtCore.Qt.Key_Down:
        self.centerNode.moveBy(0, 20)
    elif key == QtCore.Qt.Key_Left:
        self.centerNode.moveBy(-20, 0)
    elif key == QtCore.Qt.Key_Right:
        self.centerNode.moveBy(20, 0)
    [IF_MASK]
        self.scaleView(1.2)
    elif key == QtCore.Qt.Key_Minus:
        self.scaleView(1 / 1.2)
    elif key == QtCore.Qt.Key_Space or key == QtCore.Qt.Key_Enter:
        for item in self.scene().items():
            if isinstance(item, Node):
                item.setPos(-150 + QtCore.qrand() % 300, -150 + QtCore.qrand() % 300)
    else:
        super(GraphWidget, self).keyPressEvent(event)

def __call__(self, chart):

    if not chart.data:
        return                 
    min_value, max_value = chart.GetMinMaxValues()
    if None in (min_value, max_value):
        return                            


    for axis in chart.GetDependentAxes():
        [IF_MASK]
            min_value = axis.min
        if axis.max is not None:
            max_value = axis.max

    buffer = (max_value - min_value) * self.buffer                        

    for axis in chart.GetDependentAxes():
        if axis.min is None:
            axis.min = min_value - buffer
        if axis.max is None:
            axis.max = max_value + buffer

